{"command": "cd /tmp && python3 - <<'PY'
import subprocess, shutil, os
cfg="/tmp/kp4.toml"
def t(content, args=("list",)):
    open(cfg,'w').write(content)
    return subprocess.run(["/workspace/executable","-c",cfg]+list(args),capture_output=True,text=True)
cases = {
 "no default section": "[scripts.x]\ncommand = 'echo hi'\n",
 "empty scripts table": "[scripts.x]\n\n[default]\n",
 "no scripts key": "[default]\ncommand_width = 20\n",
 "empty file": "",
 "only default": "[default]\n",
 "scripts not a table": "scripts = 5\n",
 "scripts array": "[[scripts]]\ncommand='x'\n",
 "default scalar": "default = 5\n",
 "tags int elem": "[scripts.x]\ncommand='hi'\ntags = [1,2]\n",
 "top level unknown": "[scripts.x]\ncommand='hi'\nzzz = 1\n",
 "description empty": "[scripts.x]\ncommand='hi'\ndescription = ''\n",
 "tags empty": "[scripts.x]\ncommand='hi'\ntags = []\n",
}
for n,c in cases.items():
    r=t(c)
    print("=== %s rc=%d" % (n, r.returncode))
    if r.returncode: print("   ERR:", r.stderr.strip())
    else: print("   OUT:", r.stdout.strip().replace("\n","\n        "))
