#[derive(Debug, Clone, PartialEq)]
enum Token {
    Whitespace,
    Newline,
    Comment,
    Equals,
    Period,
    Comma,
    Colon,
    PlusSign,
    LeftBrace,
    RightBrace,
    LeftBracket,
    RightBracket,
    Keylike(String),
    Str { val: String, multiline: bool, raw: bool },
}

impl Token {
    fn describe(&self) -> &'static str {
        match self {
            Token::Whitespace => "whitespace",
            Token::Newline => "newline",
            Token::Comment => "a comment",
            Token::Equals => "an equals",
            Token::Period => "a period",
            Token::Comma => "a comma",
            Token::Colon => "a colon",
            Token::PlusSign => "a plus sign",
            Token::LeftBrace => "a left brace",
            Token::RightBrace => "a right brace",
            Token::LeftBracket => "a left bracket",
            Token::RightBracket => "a right bracket",
            Token::Keylike(_) => "an identifier",
            Token::Str { .. } => "a string",
        }
    }
}

pub struct Tokenizer<'a> {
    src: &'a [u8],
    pos: usize,
    line: usize,
}

fn is_keylike(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'-' || b == b'_'
}

impl<'a> Tokenizer<'a> {
    pub fn new(src: &'a str) -> Tokenizer<'a> {
        Tokenizer { src: src.as_bytes(), pos: 0, line: 1 }
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }
    fn peek2(&self) -> Option<u8> {
        self.src.get(self.pos + 1).copied()
    }
    fn peek3(&self) -> Option<u8> {
        self.src.get(self.pos + 2).copied()
    }

    fn line_of(&self, at: usize) -> usize {
        let mut l = 1;
        for i in 0..at.min(self.src.len()) {
            if self.src[i] == b'\n' {
                l += 1;
            }
        }
        l
    }

    fn err_at(&self, at: usize, e: TokErr) -> ParseError {
        ParseError { msg: e.message(), line: Some(self.line_of(at)), key: None }
    }

    fn eof_err(&self) -> ParseError {
        ParseError { msg: TokErr::UnexpectedEof.message(), line: Some(self.line), key: None }
    }

    pub fn next_token(&mut self) -> Result<Option<(Token, usize)>, ParseError> {
        let start = self.pos;
        let c = match self.peek() {
            None => return Ok(None),
            Some(c) => c,
        };
        match c {
            b'\n' => {
                self.pos += 1;
                self.line += 1;
                Ok(Some((Token::Newline, start)))
            }
            b'\r' => {
                if self.peek2() == Some(b'\n') {
                    self.pos += 2;
                    self.line += 1;
                    Ok(Some((Token::Newline, start)))
                } else {
                    Err(self.err_at(start, TokErr::Unexpected('\r')))
                }
            }
            b' ' | b'\t' => {
                while let Some(c) = self.peek() {
                    if c == b' ' || c == b'\t' {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                Ok(Some((Token::Whitespace, start)))
            }
            b'#' => {
                while let Some(c) = self.peek() {
                    if c == b'\n' {
                        break;
                    }
                    self.pos += 1;
                }
                Ok(Some((Token::Comment, start)))
            }
            b'=' => {
                self.pos += 1;
                Ok(Some((Token::Equals, start)))
            }
            b'.' => {
                self.pos += 1;
                Ok(Some((Token::Period, start)))
            }
            b',' => {
                self.pos += 1;
                Ok(Some((Token::Comma, start)))
            }
            b':' => {
                self.pos += 1;
                Ok(Some((Token::Colon, start)))
            }
            b'+' => {
                self.pos += 1;
                Ok(Some((Token::PlusSign, start)))
            }
            b'{' => {
                self.pos += 1;
                Ok(Some((Token::LeftBrace, start)))
            }
            b'}' => {
                self.pos += 1;
                Ok(Some((Token::RightBrace, start)))
            }
            b'[' => {
                self.pos += 1;
                Ok(Some((Token::LeftBracket, start)))
            }
            b']' => {
                self.pos += 1;
                Ok(Some((Token::RightBracket, start)))
            }
            b'\'' => self.literal_string(start),
            b'"' => self.basic_string(start),
            _ if is_keylike(c) => {
                let s = start;
                while let Some(c) = self.peek() {
                    if is_keylike(c) {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                let text = String::from_utf_lossy(&self.src[s..self.pos]).to_string();
                Ok(Some((Token::Keylike(text), s)))
            }
            _ => Err(self.err_at(start, TokErr::Unexpected(c as char))),
        }
    }

    fn literal_string(&mut self, start: usize) -> Result<Option<(Token, usize)>, ParseError> {
        // already at '\''
        let multi = self.peek2() == Some(b'\'') && self.peek3() == Some(b'\'');
        if multi {
            self.pos += 3;
            // trim first newline
            if self.peek() == Some(b'\r') && self.peek2() == Some(b'\n') {
                self.pos += 2;
            } else if self.peek() == Some(b'\n') {
                self.pos += 1;
            }
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err()),
                    Some(b'\'') => {
                        if self.peek2() == Some(b'\'') && self.peek3() == Some(b'\'') {
                            self.pos += 3;
                            break;
                        } else {
                            out.push(b'\'');
                            self.pos += 1;
                        }
                    }
                    Some(c) => {
                        if c == b'\n' {
                            self.line += 1;
                        }
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            let val = match String::from_utf8(out) {
                Ok(s) => s,
                Err(_) => return Err(self.err_at(start, TokErr::InvalidCharInString('\u{fffd}'))),
            };
            Ok(Some((Token::Str { val, multiline: true, raw: true }, start)))
        } else {
            self.pos += 1;
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err()),
                    Some(b'\n') => return Err(self.err_at(self.pos, TokErr::NewlineInString)),
                    Some(b'\'') => {
                        self.pos += 1;
                        break;
                    }
                    Some(c) => {
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            let val = match String::from_utf8(out) {
                Ok(s) => s,
                Err(_) => return Err(self.err_at(start, TokErr::InvalidCharInString('\u{fffd}'))),
            };
            Ok(Some((Token::Str { val, multiline: false, raw: true }, start)))
        }
    }

    fn basic_string(&mut self, start: usize) -> Result<Option<(Token, usize)>, ParseError> {
        let multi = self.peek2() == Some(b'"') && self.peek3() == Some(b'"');
        if multi {
            self.pos += 3;
            if self.peek() == Some(b'\r') && self.peek2() == Some(b'\n') {
                self.pos += 2;
            } else if self.peek() == Some(b'\n') {
                self.pos += 1;
            }
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err()),
                    Some(b'"') => {
                        if self.peek2() == Some(b'"') && self.peek3() == Some(b'"') {
                            self.pos += 3;
                            break;
                        } else {
                            out.push(b'"');
                            self.pos += 1;
                        }
                    }
                    Some(b'\\') => {
                        self.pos += 1;
                        self.escape(&mut out)?;
                    }
                    Some(b'\n') => {
                        self.line += 1;
                        out.push(b'\n');
                        self.pos += 1;
                    }
                    Some(c) => {
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            let val = match String::from_utf8(out) {
                Ok(s) => s,
                Err(_) => return Err(self.err_at(start, TokErr::InvalidCharInString('\u{fffd}'))),
            };
            Ok(Some((Token::Str { val, multiline: true, raw: false }, start)))
        } else {
            self.pos += 1;
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err()),
                    Some(b'\n') => return Err(self.err_at(self.pos, TokErr::NewlineInString)),
                    Some(b'"') => {
                        self.pos += 1;
                        break;
                    }
                    Some(b'\\') => {
                        self.pos += 1;
                        self.escape(&mut out)?;
                    }
                    Some(c) => {
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            let val = match String::from_utf8(out) {
                Ok(s) => s,
                Err(_) => return Err(self.err_at(start, TokErr::InvalidCharInString('\u{fffd}'))),
            };
            Ok(Some((Token::Str { val, multiline: false, raw: false }, start)))
        }
    }

    fn escape(&mut self, out: &mut Vec<u8>) -> Result<(), ParseError> {
        let at = self.pos;
        let c = match self.peek() {
            None => return Err(self.eof_err()),
            Some(c) => c,
        };
        self.pos += 1;
        match c {
            b'b' => out.push(8),
            b't' => out.push(b'\t'),
            b'n' => out.push(b'\n'),
            b'f' => out.push(12),
            b'r' => out.push(b'\r'),
            b'"' => out.push(b'"'),
            b'\\' => out.push(b'\\'),
            b'u' | b'U' => {
                let n = if c == b'u' { 4 } else { 8 };
                let mut v: u32 = 0;
                for _ in 0..n {
                    let d = match self.peek() {
                        None => return Err(self.eof_err()),
                        Some(d) => d,
                    };
                    let h = (d as char).to_digit(16);
                    match h {
                        None => {
                            self.pos += 1;
                            return Err(self
                                .err_at(at, TokErr::InvalidHexEscape(d as char)));
                        }
                        Some(h) => {
                            v = v * 16 + h;
                            self.pos += 1;
                        }
                    }
                }
                match std::char::from_u32(v) {
                    None => return Err(self.err_at(at, TokErr::InvalidEscapeValue(v))),
                    Some(ch) => {
                        let mut buf = [0u8; 4];
                        out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                    }
                }
            }
            _ => return Err(self.err_at(at, TokErr::InvalidEscape(c as char))),
        }
        Ok(())
    }
}

#[derive(Debug, Clone)]
pub struct ParseError {
    pub msg: String,
    pub line: Option<usize>,
    pub key: Option<String>,
}

impl ParseError {
    pub fn to_display(&self) -> String {
        let mut s = self.msg.clone();
        if let Some(k) = &self.key {
            s.push_str(&format!(" for key `{}`", k));
        }
        if let Some(l) = self.line {
            s.push_str(&format!(" at line {}", l));
        }
        s
    }
}

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

struct Parser<'a> {
    t: Tokenizer<'a>,
    peeked: Option<Option<(Token, usize)>>,
    cur_line: usize,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(src: &'a str) -> Parser<'a> {
        Parser { t: Tokenizer::new(src), peeked: None, cur_line: 1, pos: 0 }
    }

    fn peek(&mut self) -> Result<Option<(Token, usize)>, ParseError> {
        if self.peeked.is_none() {
            let n = self.t.next_token()?;
            self.peeked = Some(n);
        }
        Ok(self.peeked.as_ref().unwrap().clone())
    }

    fn next(&mut self) -> Result<Option<(Token, usize)>, ParseError> {
        if let Some(p) = self.peeked.take() {
            if let Some((tok, at)) = &p {
                self.cur_line = self.t.line_of(*at);
                self.pos = *at;
            }
            return Ok(p);
        }
        let n = self.t.next_token()?;
        if let Some((tok, at)) = &n {
            self.cur_line = self.t.line_of(*at);
            self.pos = *at;
        }
        Ok(n)
    }

    fn expect(&mut self, expected: &'static str) -> Result<(Token, usize), ParseError> {
        match self.next()? {
            None => Err(ParseError {
                msg: TokErr::UnexpectedEof.message(),
                line: Some(self.cur_line),
                key: None,
            }),
            Some((tok, at)) => Ok((tok, at)),
        }
    }

    fn skip_ws_comments_newlines(&mut self) -> Result<(), ParseError> {
        loop {
            match self.peek()? {
                Some((Token::Whitespace, _))
                | Some((Token::Comment, _))
                | Some((Token::Newline, _)) => {
                    self.next()?;
                }
                _ => return Ok(()),
            }
        }
    }

    fn skip_inline_ws(&mut self) -> Result<(), ParseError> {
        while let Some((Token::Whitespace, _)) = self.peek()? {
            self.next()?;
        }
        Ok(())
    }
}

fn token_name(tok: &Token) -> &'static str {
    tok.describe()
}

pub fn parse(src: &str) -> Result<Value, ParseError> {
    let mut p = Parser::new(src);
    let root: Vec<(String, Value)> = Vec::new();
    let mut root = root;
    // current table path
    let mut cur: Vec<String> = Vec::new();
    let mut tables: Vec<Vec<String>> = Vec::new(); // defined table headers
    let mut arrays: Vec<Vec<String>> = Vec::new(); // array-of-tables headers

    loop {
        p.skip_ws_comments_newlines()?;
        let (tok, at) = match p.peek()? {
            None => break,
            Some(x) => x,
        };
        match tok {
            Token::LeftBracket => {
                p.next()?;
                let array = if let Some((Token::LeftBracket, _)) = p.peek()? {
                    p.next()?;
