// Minimal TOML value model + parser/serializer that reproduces the messages and
// formatting of the `toml` crate (0.5.x) as used by the original program.

#[derive(Debug, Clone)]
pub enum Value {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Datetime, // represented as a "map" by the deserializer
    Array(Vec<Value>),
    Table(Vec<(String, Value)>),
}

impl Value {
    pub fn get(&self, k: &str) -> Option<&Value> {
        match self {
            Value::Table(v) => v.iter().find(|(key, _)| key == k).map(|(_, x)| x),
            _ => None,
        }
    }
    pub fn is_table(&self) -> bool {
        matches!(*self, Value::Table(_))
    }
    /// serde's "unexpected" rendering used inside `invalid type` messages.
    pub fn unexpected(&self) -> String {
        match self {
            Value::Str(s) => format!("string {:?}", s),
            Value::Int(i) => format!("integer `{}`", i),
            Value::Float(f) => format!("floating point `{}`", fmt_float(*f)),
            Value::Bool(b) => format!("boolean `{}`", b),
            // toml treats datetimes as a map of parts
            Value::Datetime => "map".to_string(),
            Value::Array(_) => "sequence".to_string(),
            Value::Table(_) => "map".to_string(),
        }
    }
}

pub fn fmt_float(f: f64) -> String {
    if f.is_nan() {
        "NaN".to_string()
    } else if f.is_infinite() {
        if f > 0.0 { "inf".to_string() } else { "-inf".to_string() }
    } else {
        let s = format!("{}", f);
        s
    }
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub enum TokErr {
    UnexpectedEof,
    InvalidCharInString(char),
    InvalidEscape(char),
    InvalidHexEscape(char),
    InvalidEscapeValue(u32),
    NewlineInString,
    Unexpected(char),
    UnterminatedString,
    NewlineInTableKey,
    MultilineStringKey,
    Wanted { expected: &'static str, found: &'static str },
    NumberInvalid,
    DateInvalid,
    DuplicateTable(String),
    RedefineAsArray,
    EmptyTableKey,
    MixedTableArray,
}

fn esc_default(c: char) -> String {
    match c {
        '\u{7}' => "\\u{7}".to_string(),
        '\u{8}' => "\\u{8}".to_string(),
        '\t' => "\\t".to_string(),
        '\n' => "\\n".to_string(),
        '\r' => "\\r".to_string(),
        '\u{b}' => "\\u{b}".to_string(),
        '\u{c}' => "\\u{c}".to_string(),
        '\0' => "\\0".to_string(),
        _ => c.to_string(),
    }
}

impl TokErr {
    pub fn message(&self) -> String {
        match self {
            TokErr::UnexpectedEof => "unexpected eof encountered".to_string(),
            TokErr::InvalidCharInString(c) => {
                format!("invalid character in string: `{}`", esc_default(*c))
            }
            TokErr::InvalidEscape(c) => format!(
                "invalid escape character in string: `{}`",
                esc_default(*c)
            ),
            TokErr::InvalidHexEscape(c) => format!(
                "invalid hex escape character in string: `{}`",
                esc_default(*c)
            ),
            TokErr::InvalidEscapeValue(v) => format!("invalid escape value: `{}`", v),
            TokErr::NewlineInString => "newline in string found".to_string(),
            TokErr::Unexpected(c) => {
                format!("unexpected character found: `{}`", esc_default(*c))
            }
            TokErr::UnterminatedString => "unterminated string".to_string(),
            TokErr::NewlineInTableKey => "newline in table key found".to_string(),
            TokErr::MultilineStringKey => "multiline strings are not allowed for key".to_string(),
            TokErr::Wanted { expected, found } => {
                format!("expected {}, found {}", expected, found)
            }
            TokErr::NumberInvalid => "invalid number".to_string(),
            TokErr::DateInvalid => "invalid date".to_string(),
            TokErr::DuplicateTable(s) => format!("redefinition of table `{}`", s),
            TokErr::RedefineAsArray => "table redefined as array".to_string(),
            TokErr::EmptyTableKey => "empty table key found".to_string(),
            TokErr::MixedTableArray => "key redefined as table/array".to_string(),
        }
    }
}

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Whitespace,
    Newline,
    Comment,
    Equals,
    Period,
    Comma,
    Colon,
    PlusSign,
    LeftBrace,
    RightBrace,
    LeftBracket,
    RightBracket,
    Keylike(String),
    Str { val: String, multiline: bool, raw: bool },
}

impl Token {
    fn describe(&self) -> &'static str {
        match self {
            Token::Whitespace => "whitespace",
            Token::Newline => "newline",
            Token::Comment => "a comment",
            Token::Equals => "an equals",
            Token::Period => "a period",
            Token::Comma => "a comma",
            Token::Colon => "a colon",
            Token::PlusSign => "a plus sign",
            Token::LeftBrace => "a left brace",
            Token::RightBrace => "a right brace",
            Token::LeftBracket => "a left bracket",
            Token::RightBracket => "a right bracket",
            Token::Keylike(_) => "an identifier",
            Token::Str { .. } => "a string",
        }
    }
}

pub struct Tokenizer<'a> {
    src: &'a [u8],
    pos: usize,
    line: usize,
}

fn is_keylike(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'-' || b == b'_'
}

impl<'a> Tokenizer<'a> {
    pub fn new(src: &'a str) -> Tokenizer<'a> {
        Tokenizer { src: src.as_bytes(), pos: 0, line: 1 }
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }
    fn peek2(&self) -> Option<u8> {
        self.src.get(self.pos + 1).copied()
    }
    fn peek3(&self) -> Option<u8> {
        self.src.get(self.pos + 2).copied()
    }

    fn line_of(&self, at: usize) -> usize {
        let mut l = 1;
        for i in 0..at.min(self.src.len()) {
            if self.src[i] == b'\n' {
                l += 1;
            }
        }
        l
    }

    fn err_at(&self, at: usize, e: TokErr) -> ParseError {
        ParseError { msg: e.message(), line: Some(self.line_of(at)), key: None }
    }

    fn eof_err(&self) -> ParseError {
        ParseError { msg: TokErr::UnexpectedEof.message(), line: Some(self.line), key: None }
    }

    pub fn next_token(&mut self) -> Result<Option<(Token, usize)>, ParseError> {
        let start = self.pos;
        let c = match self.peek() {
            None => return Ok(None),
            Some(c) => c,
        };
        match c {
            b'\n' => {
                self.pos += 1;
                self.line += 1;
                Ok(Some((Token::Newline, start)))
            }
            b'\r' => {
                if self.peek2() == Some(b'\n') {
                    self.pos += 2;
                    self.line += 1;
                    Ok(Some((Token::Newline, start)))
                } else {
                    Err(self.err_at(start, TokErr::Unexpected('\r')))
                }
            }
            b' ' | b'\t' => {
                while let Some(c) = self.peek() {
                    if c == b' ' || c == b'\t' {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                Ok(Some((Token::Whitespace, start)))
            }
            b'#' => {
                while let Some(c) = self.peek() {
                    if c == b'\n' {
                        break;
                    }
                    self.pos += 1;
                }
                Ok(Some((Token::Comment, start)))
            }
            b'=' => {
                self.pos += 1;
                Ok(Some((Token::Equals, start)))
            }
            b'.' => {
                self.pos += 1;
                Ok(Some((Token::Period, start)))
            }
            b',' => {
                self.pos += 1;
                Ok(Some((Token::Comma, start)))
            }
            b':' => {
                self.pos += 1;
                Ok(Some((Token::Colon, start)))
            }
            b'+' => {
                self.pos += 1;
                Ok(Some((Token::PlusSign, start)))
            }
            b'{' => {
                self.pos += 1;
                Ok(Some((Token::LeftBrace, start)))
            }
            b'}' => {
                self.pos += 1;
                Ok(Some((Token::RightBrace, start)))
            }
            b'[' => {
                self.pos += 1;
                Ok(Some((Token::LeftBracket, start)))
            }
            b']' => {
                self.pos += 1;
                Ok(Some((Token::RightBracket, start)))
            }
            b'\'' => self.literal_string(start),
            b'"' => self.basic_string(start),
            _ if is_keylike(c) => {
                let s = start;
                while let Some(c) = self.peek() {
                    if is_keylike(c) {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                let text = String::from_utf_lossy(&self.src[s..self.pos]).to_string();
                Ok(Some((Token::Keylike(text), s)))
            }
            _ => Err(self.err_at(start, TokErr::Unexpected(c as char))),
        }
    }

    fn literal_string(&mut self, start: usize) -> Result<Option<(Token, usize)>, ParseError> {
        // already at '\''
        let multi = self.peek2() == Some(b'\'') && self.peek3() == Some(b'\'');
        if multi {
            self.pos += 3;
            // trim first newline
            if self.peek() == Some(b'\r') && self.peek2() == Some(b'\n') {
                self.pos += 2;
            } else if self.peek() == Some(b'\n') {
                self.pos += 1;
            }
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err()),
                    Some(b'\'') => {
                        if self.peek2() == Some(b'\'') && self.peek3() == Some(b'\'') {
                            self.pos += 3;
                            break;
                        } else {
                            out.push(b'\'');
                            self.pos += 1;
                        }
                    }
                    Some(c) => {
                        if c == b'\n' {
                            self.line += 1;
                        }
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            let val = match String::from_utf8(out) {
                Ok(s) => s,
                Err(_) => return Err(self.err_at(start, TokErr::InvalidCharInString('\u{fffd}'))),
            };
            Ok(Some((Token::Str { val, multiline: true, raw: true }, start)))
        } else {
            self.pos += 1;
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err()),
                    Some(b'\n') => return Err(self.err_at(self.pos, TokErr::NewlineInString)),
                    Some(b'\'') => {
                        self.pos += 1;
                        break;
                    }
                    Some(c) => {
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            let val = match String::from_utf8(out) {
                Ok(s) => s,
                Err(_) => return Err(self.err_at(start, TokErr::InvalidCharInString('\u{fffd}'))),
            };
            Ok(Some((Token::Str { val, multiline: false, raw: true }, start)))
        }
    }

    fn basic_string(&mut self, start: usize) -> Result<Option<(Token, usize)>, ParseError> {
        let multi = self.peek2() == Some(b'"') && self.peek3() == Some(b'"');
        if multi {
            self.pos += 3;
            if self.peek() == Some(b'\r') && self.peek2() == Some(b'\n') {
                self.pos += 2;
            } else if self.peek() == Some(b'\n') {
                self.pos += 1;
            }
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err()),
                    Some(b'"') => {
                        if self.peek2() == Some(b'"') && self.peek3() == Some(b'"') {
                            self.pos += 3;
                            break;
                        } else {
                            out.push(b'"');
                            self.pos += 1;
                        }
                    }
                    Some(b'\\') => {
                        self.pos += 1;
                        self.escape(&mut out)?;
                    }
                    Some(b'\n') => {
                        self.line += 1;
                        out.push(b'\n');
                        self.pos += 1;
                    }
                    Some(c) => {
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            let val = match String::from_utf8(out) {
                Ok(s) => s,
                Err(_) => return Err(self.err_at(start, TokErr::InvalidCharInString('\u{fffd}'))),
            };
            Ok(Some((Token::Str { val, multiline: true, raw: false }, start)))
        } else {
            self.pos += 1;
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err()),
                    Some(b'\n') => return Err(self.err_at(self.pos, TokErr::NewlineInString)),
                    Some(b'"') => {
                        self.pos += 1;
                        break;
                    }
                    Some(b'\\') => {
                        self.pos += 1;
                        self.escape(&mut out)?;
                    }
                    Some(c) => {
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            let val = match String::from_utf8(out) {
                Ok(s) => s,
                Err(_) => return Err(self.err_at(start, TokErr::InvalidCharInString('\u{fffd}'))),
            };
            Ok(Some((Token::Str { val, multiline: false, raw: false }, start)))
        }
    }

    fn escape(&mut self, out: &mut Vec<u8>) -> Result<(), ParseError> {
        let at = self.pos;
        let c = match self.peek() {
            None => return Err(self.eof_err()),
            Some(c) => c,
        };
        self.pos += 1;
        match c {
            b'b' => out.push(8),
            b't' => out.push(b'\t'),
            b'n' => out.push(b'\n'),
            b'f' => out.push(12),
            b'r' => out.push(b'\r'),
            b'"' => out.push(b'"'),
            b'\\' => out.push(b'\\'),
            b'u' | b'U' => {
                let n = if c == b'u' { 4 } else { 8 };
                let mut v: u32 = 0;
                for _ in 0..n {
                    let d = match self.peek() {
                        None => return Err(self.eof_err()),
                        Some(d) => d,
                    };
                    let h = (d as char).to_digit(16);
                    match h {
                        None => {
                            self.pos += 1;
                            return Err(self
                                .err_at(at, TokErr::InvalidHexEscape(d as char)));
                        }
                        Some(h) => {
                            v = v * 16 + h;
                            self.pos += 1;
                        }
                    }
                }
                match std::char::from_u32(v) {
                    None => return Err(self.err_at(at, TokErr::InvalidEscapeValue(v))),
                    Some(ch) => {
                        let mut buf = [0u8; 4];
                        out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                    }
                }
            }
            _ => return Err(self.err_at(at, TokErr::InvalidEscape(c as char))),
        }
        Ok(())
    }
}

#[derive(Debug, Clone)]
pub struct ParseError {
    pub msg: String,
    pub line: Option<usize>,
    pub key: Option<String>,
}

impl ParseError {
    pub fn to_display(&self) -> String {
        let mut s = self.msg.clone();
        if let Some(k) = &self.key {
            s.push_str(&format!(" for key `{}`", k));
        }
        if let Some(l) = self.line {
            s.push_str(&format!(" at line {}", l));
        }
        s
    }
}

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

struct Parser<'a> {
    t: Tokenizer<'a>,
    peeked: Option<Option<(Token, usize)>>,
    cur_line: usize,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(src: &'a str) -> Parser<'a> {
        Parser { t: Tokenizer::new(src), peeked: None, cur_line: 1, pos: 0 }
    }

    fn peek(&mut self) -> Result<Option<(Token, usize)>, ParseError> {
        if self.peeked.is_none() {
            let n = self.t.next_token()?;
            self.peeked = Some(n);
        }
        Ok(self.peeked.as_ref().unwrap().clone())
    }

    fn next(&mut self) -> Result<Option<(Token, usize)>, ParseError> {
        if let Some(p) = self.peeked.take() {
            if let Some((tok, at)) = &p {
                self.cur_line = self.t.line_of(*at);
                self.pos = *at;
            }
            return Ok(p);
        }
        let n = self.t.next_token()?;
        if let Some((tok, at)) = &n {
            self.cur_line = self.t.line_of(*at);
            self.pos = *at;
        }
        Ok(n)
    }

    fn expect(&mut self, expected: &'static str) -> Result<(Token, usize), ParseError> {
        match self.next()? {
            None => Err(ParseError {
                msg: TokErr::UnexpectedEof.message(),
                line: Some(self.cur_line),
                key: None,
            }),
            Some((tok, at)) => Ok((tok, at)),
        }
    }

    fn skip_ws_comments_newlines(&mut self) -> Result<(), ParseError> {
        loop {
            match self.peek()? {
                Some((Token::Whitespace, _))
                | Some((Token::Comment, _))
                | Some((Token::Newline, _)) => {
                    self.next()?;
                }
                _ => return Ok(()),
            }
        }
    }

    fn skip_inline_ws(&mut self) -> Result<(), ParseError> {
        while let Some((Token::Whitespace, _)) = self.peek()? {
            self.next()?;
        }
        Ok(())
    }
}

fn token_name(tok: &Token) -> &'static str {
    tok.describe()
}

pub fn parse(src: &str) -> Result<Value, ParseError> {
    let mut p = Parser::new(src);
    let root: Vec<(String, Value)> = Vec::new();
    let mut root = root;
    // current table path
    let mut cur: Vec<String> = Vec::new();
    let mut tables: Vec<Vec<String>> = Vec::new(); // defined table headers
    let mut arrays: Vec<Vec<String>> = Vec::new(); // array-of-tables headers

    loop {
        p.skip_ws_comments_newlines()?;
        let (tok, at) = match p.peek()? {
            None => break,
            Some(x) => x,
        };
        match tok {
            Token::LeftBracket => {
                p.next()?;
                let array = if let Some((Token::LeftBracket, _)) = p.peek()? {
                    p.next()?;
                    true
                } else {
                    false
                };
                let keys = parse_key_path(&mut p)?;
                p.skip_inline_ws()?;
                match p.peek()? {
                    Some((Token::RightBracket, _)) => {
                        p.next()?;
                    }
                    Some((t, a)) => {
                        return Err(ParseError {
                            msg: TokErr::Wanted {
                                expected: "a right bracket",
                                found: token_name(&t),
                            }
                            .message(),
                            line: Some(p.t.line_of(a)),
                            key: None,
                        })
                    }
                    None => {
                        return Err(ParseError {
                            msg: TokErr::UnexpectedEof.message(),
                            line: Some(p.cur_line),
                            key: None,
                        })
                    }
                }
                if array {
                    if let Some((Token::LeftBracket, _)) = p.peek()? {
                        p.next()?;
                    } else {
                        let (t, a) = match p.peek()? {
                            Some(x) => x,
                            None => {
                                return Err(ParseError {
                                    msg: TokErr::UnexpectedEof.message(),
                                    line: Some(p.cur_line),
                                    key: None,
                                })
                            }
                        };
                        return Err(ParseError {
                            msg: TokErr::Wanted {
                                expected: "a right bracket",
                                found: token_name(&t),
                            }
                            .message(),
                            line: Some(p.t.line_of(a)),
                            key: None,
                        });
                    }
                }
                p.skip_inline_ws()?;
                // must be followed by newline/comment/eof
                match p.peek()? {
                    None => {}
                    Some((Token::Comment, _)) | Some((Token::Newline, _)) => {}
                    Some((t, a)) => {
                        return Err(ParseError {
                            msg: TokErr::Wanted {
                                expected: "newline",
                                found: token_name(&t),
                            }
                            .message(),
                            line: Some(p.t.line_of(a)),
                            key: None,
                        })
                    }
                }
                // register the table
                let full = keys.clone();
                let joined = full.join(".");
                if array {
                    if tables.contains(&full) {
                        return Err(ParseError {
                            msg: TokErr::DuplicateTable(joined).message(),
                            line: Some(p.t.line_of(at)),
                            key: Some(joined.clone()),
                        });
                    }
                    arrays.push(full.clone());
                } else {
                    if tables.contains(&full) || arrays.contains(&full) {
                        return Err(ParseError {
                            msg: TokErr::DuplicateTable(joined.clone()).message(),
                            line: Some(p.t.line_of(at)),
                            key: Some(joined.clone()),
                        });
                    }
                    // also error if an ancestor was an array
                    tables.push(full.clone());
                }
                cur = full;
            }
            Token::Keylike(_) | Token::Str { .. } => {
                let keys = parse_key_path(&mut p)?;
                p.skip_inline_ws()?;
                match p.peek()? {
                    Some((Token::Equals, _)) => {
                        p.next()?;
                    }
                    Some((t, a)) => {
                        return Err(ParseError {
                            msg: TokErr::Wanted {
                                expected: "an equals",
                                found: token_name(&t),
                            }
                            .message(),
                            line: Some(p.t.line_of(a)),
                            key: None,
                        })
                    }
                    None => {
                        return Err(ParseError {
                            msg: TokErr::UnexpectedEof.message(),
                            line: Some(p.cur_line),
                            key: None,
                        })
                    }
                }
                p.skip_inline_ws()?;
                let val = parse_value(&mut p)?;
                // insert
                let mut path = cur.clone();
                path.extend(keys.iter().cloned());
                insert_value(&mut root, &path, val, p.t.line_of(at), &mut tables)?;
                p.skip_inline_ws()?;
                match p.peek()? {
                    None => {}
                    Some((Token::Comment, _)) | Some((Token::Newline, _)) => {
                        p.next()?;
                    }
                    Some((t, a)) => {
                        return Err(ParseError {
                            msg: TokErr::Wanted {
                                expected: "newline",
                                found: token_name(&t),
                            }
                            .message(),
                            line: Some(p.t.line_of(a)),
                            key: None,
                        })
                    }
                }
            }
            _ => {
                return Err(ParseError {
                    msg: TokErr::Wanted {
                        expected: "a table key",
                        found: token_name(&tok),
                    }
                    .message(),
                    line: Some(p.t.line_of(at)),
                    key: None,
                })
            }
        }
    }
    Ok(Value::Table(root))
}

fn parse_key_path(p: &mut Parser) -> Result<Vec<String>, ParseError> {
    let mut keys = Vec::new();
    loop {
        p.skip_inline_ws()?;
        let (tok, at) = match p.next()? {
            None => {
                return Err(ParseError {
                    msg: TokErr::UnexpectedEof.message(),
                    line: Some(p.cur_line),
                    key: None,
                })
            }
            Some(x) => x,
        };
        let k = match tok {
            Token::Keylike(s) => s,
            Token::Str { val, multiline, .. } => {
                if multiline {
                    return Err(ParseError {
                        msg: TokErr::MultilineStringKey.message(),
                        line: Some(p.t.line_of(at)),
                        key: None,
                    });
                }
                if val.is_empty() {
                    return Err(ParseError {
                        msg: TokErr::EmptyTableKey.message(),
                        line: Some(p.t.line_of(at)),
                        key: None,
                    });
                }
                val
            }
            t => {
                return Err(ParseError {
                    msg: TokErr::Wanted {
                        expected: "a table key",
                        found: token_name(&t),
                    }
                    .message(),
                    line: Some(p.t.line_of(at)),
                    key: None,
                })
            }
        };
        keys.push(k);
        p.skip_inline_ws()?;
        match p.peek()? {
            Some((Token::Period, _)) => {
                p.next()?;
            }
            _ => break,
        }
    }
    Ok(keys)
}

fn insert_value(
    root: &mut Vec<(String, Value)>,
    path: &[String],
    val: Value,
    line: usize,
    tables: &mut Vec<Vec<String>>,
) -> Result<(), ParseError> {
    if path.is_empty() {
        return Ok(());
    }
    let key = path[0].clone();
    if path.len() == 1 {
        if let Some(idx) = root.iter().position(|(k, _)| *k == key) {
            // duplicate key: for tables we let the caller decide; here we replace
            root[idx].1 = val;
        } else {
            root.push((key, val));
        }
        return Ok(());
    }
    let idx = match root.iter().position(|(k, _)| *k == key) {
        Some(i) => i,
        None => {
            root.push((key.clone(), Value::Table(Vec::new())));
            root.len() - 1
        }
    };
    match &mut root[idx].1 {
        Value::Table(t) => insert_value(t, &path[1..], val, line, tables),
        Value::Array(arr) => match arr.last_mut() {
            Some(Value::Table(t)) => insert_value(t, &path[1..], val, line, tables),
            _ => Err(ParseError {
                msg: TokErr::MixedTableArray.message(),
                line: Some(line),
                key: Some(path.join(".")),
            }),
        },
        _ => Err(ParseError {
            msg: TokErr::MixedTableArray.message(),
            line: Some(line),
            key: Some(path.join(".")),
        }),
    }
}

fn parse_value(p: &mut Parser) -> Result<Value, ParseError> {
    let (tok, at) = match p.next()? {
        None => {
            return Err(ParseError {
                msg: TokErr::UnexpectedEof.message(),
                line: Some(p.cur_line),
                key: None,
            })
        }
        Some(x) => x,
    };
    match tok {
        Token::Str { val, .. } => Ok(Value::Str(val)),
        Token::Keylike(s) => parse_keylike(p, s, at),
        Token::PlusSign => {
            // number with leading +
            let (t2, a2) = match p.next()? {
                None => {
                    return Err(ParseError {
                        msg: TokErr::UnexpectedEof.message(),
                        line: Some(p.cur_line),
                        key: None,
                    })
                }
                Some(x) => x,
            };
            match t2 {
                Token::Keylike(s) => parse_keylike_signed(p, &s, a2, true),
                _ => Err(ParseError {
                    msg: TokErr::NumberInvalid.message(),
                    line: Some(p.t.line_of(a2)),
                    key: None,
                }),
            }
        }
        Token::LeftBracket => parse_array(p),
        Token::LeftBrace => parse_inline_table(p),
        Token::Newline => Err(ParseError {
            msg: TokErr::Wanted {
                expected: "a value",
                found: "newline",
            }
            .message(),
            line: Some(p.t.line_of(at)),
            key: None,
        }),
        t => Err(ParseError {
            msg: TokErr::Wanted {
                expected: "a value",
                found: token_name(&t),
            }
            .message(),
            line: Some(p.t.line_of(at)),
            key: None,
        }),
    }
}

fn parse_keylike(p: &mut Parser, s: String, at: usize) -> Result<Value, ParseError> {
    parse_keylike_signed(p, &s, at, false)
}

fn parse_keylike_signed(
    p: &mut Parser,
    s: &str,
    at: usize,
    plus: bool,
) -> Result<Value, ParseError> {
    match s {
        "true" => return Ok(Value::Bool(true)),
        "false" => return Ok(Value::Bool(false)),
        "inf" => {
            if plus {
                return Ok(Value::Float(f64::INFINITY));
            }
            return Ok(Value::Float(f64::INFINITY));
        }
        "nan" => return Ok(Value::Float(f64::NAN)),
        _ => {}
    }
    // try date/time first (contains '-' or ':' in a specific pattern)
    if looks_like_datetime(s) {
        // consume remaining keylike/period/colon parts
        let mut full = s.to_string();
        loop {
            match p.peek() {
                Ok(Some((Token::Period, _))) | Ok(Some((Token::Colon, _))) => {
                    if let Ok(Some((t, _))) = p.next() {
                        match t {
                            Token::Period => full.push('.'),
                            Token::Colon => full.push(':'),
                            Token::Keylike(k) => {
                                full.push_str(&k);
                            }
                            _ => break,
                        }
                    } else {
                        break;
                    }
                    // after a period/colon there may be a keylike part
                    match p.peek() {
                        Ok(Some((Token::Keylike(k), _))) => {
                            if let Ok(Some((t2, _))) = p.next() {
                                if let Token::Keylike(k2) = t2 {
                                    full.push_str(&k2);
                                }
                            }
                        }
                        _ => break,
                    }
                }
                _ => break,
            }
        }
        // validate shape loosely
        return Ok(Value::Datetime);
    }
    // integer / float
    let cleaned: String = s.chars().filter(|c| *c != '_').collect();
    if let Some(rest) = cleaned.strip_prefix("0x") {
        match i64::from_str_radix(rest, 16) {
            Ok(v) => return Ok(Value::Int(v)),
            Err(_) => return Err(num_err(p, at)),
        }
    }
    if let Some(rest) = cleaned.strip_prefix("0o") {
        match i64::from_str_radix(rest, 8) {
            Ok(v) => return Ok(Value::Int(v)),
            Err(_) => return Err(num_err(p, at)),
        }
    }
    if let Some(rest) = cleaned.strip_prefix("0b") {
        match i64::from_str_radix(rest, 2) {
            Ok(v) => return Ok(Value::Int(v)),
            Err(_) => return Err(num_err(p, at)),
        }
    }
    if cleaned.contains('.') || cleaned.contains('e') || cleaned.contains('E') {
        // float
        let mut text = cleaned.clone();
        // handle exponents like 1e+5 written as separate tokens
        if plus {
            text = format!("+{}", text);
        }
        loop {
            match p.peek() {
                Ok(Some((Token::Period, _))) => {
                    p.next()?;
                    text.push('.');
                    match p.peek() {
                        Ok(Some((Token::Keylike(k), _))) => {
                            p.next()?;
                            text.push_str(&k.replace('_', ""));
                        }
                        _ => {}
                    }
                }
                Ok(Some((Token::PlusSign, _))) => {
                    p.next()?;
                    text.push('+');
                }
                Ok(Some((Token::Keylike(k), _))) if text.ends_with('e') || text.ends_with('E') => {
                    p.next()?;
                    text.push_str(&k.replace('_', ""));
                }
                _ => break,
            }
        }
        match text.parse::<f64>() {
            Ok(v) => return Ok(Value::Float(v)),
            Err(_) => return Err(num_err(p, at)),
        }
    }
    // integer
    let mut text = cleaned.clone();
    if plus {
        text = format!("+{}", text);
    }
    // leading zeros are invalid
    let digits = text.trim_start_matches(['+', '-']);
    if digits.len() > 1 && digits.starts_with('0') {
        return Err(num_err(p, at));
    }
    match text.parse::<i64>() {
        Ok(v) => Ok(Value::Int(v)),
        Err(_) => Err(num_err(p, at)),
    }
}

fn num_err(p: &Parser, at: usize) -> ParseError {
    ParseError {
        msg: TokErr::NumberInvalid.message(),
        line: Some(p.t.line_of(at)),
        key: None,
    }
}

fn looks_like_datetime(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() == 10
        && b[0].is_ascii_digit()
        && b[1].is_ascii_digit()
        && b[2].is_ascii_digit()
        && b[3].is_ascii_digit()
        && b[4] == b'-'
    {
        return true;
    }
    // times like 07:32:00 handled when keylike splits
    false
}

fn parse_array(p: &mut Parser) -> Result<Value, ParseError> {
    let mut out = Vec::new();
    loop {
        p.skip_ws_comments_newlines()?;
        match p.peek()? {
            Some((Token::RightBracket, _)) => {
                p.next()?;
                break;
            }
            None => {
                return Err(ParseError {
                    msg: TokErr::UnexpectedEof.message(),
                    line: Some(p.cur_line),
                    key: None,
                })
            }
            _ => {}
        }
        let v = parse_value(p)?;
        out.push(v);
        p.skip_ws_comments_newlines()?;
        match p.peek()? {
            Some((Token::Comma, _)) => {
                p.next()?;
            }
            Some((Token::RightBracket, _)) => {
                p.next()?;
                break;
            }
            None => {
                return Err(ParseError {
                    msg: TokErr::UnexpectedEof.message(),
                    line: Some(p.cur_line),
                    key: None,
                })
            }
            Some((t, a)) => {
                return Err(ParseError {
                    msg: TokErr::Wanted {
                        expected: "a comma",
                        found: token_name(&t),
                    }
                    .message(),
                    line: Some(p.t.line_of(a)),
                    key: None,
                })
            }
        }
    }
    Ok(Value::Array(out))
}

fn parse_inline_table(p: &mut Parser) -> Result<Value, ParseError> {
    let mut out: Vec<(String, Value)> = Vec::new();
    p.skip_inline_ws()?;
    if let Some((Token::RightBrace, _)) = p.peek()? {
        p.next()?;
        return Ok(Value::Table(out));
    }
    loop {
        p.skip_inline_ws()?;
        let keys = parse_key_path(p)?;
        p.skip_inline_ws()?;
        match p.next()? {
            Some((Token::Equals, _)) => {}
            Some((t, a)) => {
                return Err(ParseError {
                    msg: TokErr::Wanted {
                        expected: "an equals",
                        found: token_name(&t),
                    }
                    .message(),
                    line: Some(p.t.line_of(a)),
                    key: None,
                })
            }
            None => {
                return Err(ParseError {
                    msg: TokErr::UnexpectedEof.message(),
                    line: Some(p.cur_line),
                    key: None,
                })
            }
        }
        p.skip_inline_ws()?;
        let v = parse_value(p)?;
        // simple insertion (flat keys only supported at one level)
        insert_flat(&mut out, &keys, v);
        p.skip_inline_ws()?;
        match p.peek()? {
            Some((Token::Comma, _)) => {
                p.next()?;
            }
            Some((Token::RightBrace, _)) => {
                p.next()?;
                break;
            }
            None => {
                return Err(ParseError {
                    msg: TokErr::UnexpectedEof.message(),
                    line: Some(p.cur_line),
                    key: None,
                })
            }
            Some((t, a)) => {
                return Err(ParseError {
                    msg: TokErr::Wanted {
                        expected: "a right brace",
                        found: token_name(&t),
                    }
                    .message(),
                    line: Some(p.t.line_of(a)),
                    key: None,
                })
            }
        }
    }
    Ok(Value::Table(out))
}

fn insert_flat(t: &mut Vec<(String, Value)>, keys: &[String], v: Value) {
    if keys.len() == 1 {
        if let Some(i) = t.iter().position(|(k, _)| *k == keys[0]) {
            t[i].1 = v;
        } else {
            t.push((keys[0].clone(), v));
        }
        return;
    }
    let idx = match t.iter().position(|(k, _)| *k == keys[0]) {
        Some(i) => i,
        None => {
            t.push((keys[0].clone(), Value::Table(Vec::new())));
            t.len() - 1
        }
    };
    if let Value::Table(inner) = &mut t[idx].1 {
        insert_flat(inner, &keys[1..], v);
    }
}

// ---------------------------------------------------------------------------
// Serializer (toml's `to_string_pretty`)
// ---------------------------------------------------------------------------

pub fn is_bare_key(k: &str) -> bool {
    !k.is_empty()
        && k.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

pub fn quote_key(k: &str) -> String {
    if is_bare_key(k) {
        k.to_string()
    } else {
        format!("\"{}\"", escape_basic(k))
    }
}

fn escape_basic(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04X}", c as u32));
            }
            c => out.push(c),
        }
    }
    out
}

fn bad_for_literal(c: char) -> bool {
    c == '\'' || ((c as u32) < 0x20 && c != '\t')
}

pub fn write_string(s: &str) -> String {
    let literal_single = !s.chars().any(bad_for_literal);
    if literal_single {
        return format!("'{}'", s);
    }
    let literal_multi = !s.chars().any(bad_for_literal)
        && !s.contains("'''")
        && !s.ends_with('\'');
    if literal_multi {
        if s.contains('\n') {
            format!("'''\n{}'''", s)
        } else {
            format!("'''{}'''", s)
        }
    } else {
        if s.contains('\n') {
            format!("\"\"\"\n{}\"\"\"", escape_multiline(s))
        } else {
            format!("\"{}\"", escape_basic(s))
        }
    }
}

fn escape_multiline(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\n' => out.push('\n'),
            '\r' => out.push_str("\\r"),
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push('\t'),
            '\u{c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04X}", c as u32)),
            c => out.push(c),
        }
    }
    out
}
