{"command": "cat > /workspace/src/config.rs <<'RSEOF'
use crate::tomlv::*;
use std::collections::BTreeMap;

#[derive(Debug, Clone, Default)]
pub struct Script {
    pub command: String,
    pub description: Option<String>,
    pub tags: Option<Vec<String>>,
}

#[derive(Debug, Clone, Default)]
pub struct ConfigDefaultOpts {
    pub command_width: Option<usize>,
}

#[derive(Debug, Clone, Default)]
pub struct Config {
    pub scripts: BTreeMap<String, Script>,
    pub default: ConfigDefaultOpts,
}

pub struct DeError {
    pub msg: String,
    pub key: Option<String>,
}

impl DeError {
    pub fn to_display(&self) -> String {
        let mut s = self.msg.clone();
        if let Some(k) = &self.key {
            s.push_str(&format!(" for key `{}`", k));
        }
        s
    }
}

fn invalid_type(v: &Value, expected: &str, key: Option<String>) -> DeError {
    DeError {
        msg: format!("invalid type: {}, expected {}", v.unexpected(), expected),
        key,
    }
}

pub fn from_value(v: &Value) -> Result<Config, DeError> {
    let mut cfg = Config::default();
    let mut seen_scripts = false;
    let mut seen_default = false;
    let entries: Vec<(String, Value)> = match v {
        Value::Table(t) => t.clone(),
        _ => {
            return Err(DeError {
                msg: "invalid root value".to_string(),
                key: None,
            })
        }
    };
    for (k, val) in entries {
        match k.as_str() {
            "scripts" => {
                if seen_scripts {
                    return Err(DeError { msg: "duplicate field `scripts`".to_string(), key: None });
                }
                seen_scripts = true;
                let tbl = match val {
                    Value::Table(t) => t.clone(),
                    other => {
                        return Err(invalid_type(
                            other,
                            "map is expected",
                            Some("scripts".to_string()),
                        ))
                    }
                };
                for (alias, sv) in tbl {
                    let path = format!("scripts.{}", alias);
                    let fields = match &sv {
                        Value::Table(f) => f.clone(),
                        other => {
                            return Err(invalid_type(other, "struct Script", Some(path.clone())))
                        }
                    };
                    let script = parse_script(&alias, &fields)?;
                    cfg.scripts.insert(alias, script);
                }
            }
            "default" => {
                if seen_default {
                    return Err(DeError { msg: "duplicate field `default`".to_string(), key: None });
                }
                seen_default = true;
                let fields = match val {
                    Value::Table(f) => f.clone(),
                    other => {
                        return Err(invalid_type(
                            other,
                            "struct ConfigDefaultOpts",
                            Some("default".to_string()),
                        ))
                    }
                };
                let mut seen_cw = false;
                for (fk, fv) in fields {
                    if fk == "command_width" {
                        if seen_cw {
                            return Err(DeError {
                                msg: "duplicate field `command_width`".to_string(),
                                key: Some("default".to_string()),
                            });
                        }
                        seen_cw = true;
                        match fv {
                            Value::Int(i) => {
                                if i < 0 {
                                    return Err(DeError {
                                        msg: format!(
                                            "invalid value: integer `{}`, expected usize",
                                            i
                                        ),
                                        key: Some("default.command_width".to_string()),
                                    });
                                }
                                cfg.default.command_width = Some(i as usize);
                            }
                            other => {
                                return Err(invalid_type(
                                    &other,
                                    "usize",
                                    Some("default.command_width".to_string()),
                                ))
                            }
                        }
                    }
                }
            }
            _ => {}
        }
    }
    Ok(cfg)
}

fn parse_script(alias: &str, fields: &[(String, Value)]) -> Result<Script, DeError> {
    let path = format!("scripts.{}", alias);
    let mut script = Script::default();
    let mut seen_command = false;
    let mut seen_description = false;
    let mut seen_tags = false;
    for (k, v) in fields {
        match k.as_str() {
            "command" => {
                if seen_command {
                    return Err(DeError {
                        msg: "duplicate field `command`".to_string(),
                        key: Some(path.clone()),
                    });
                }
                seen_command = true;
                match v {
                    Value::Str(s) => script.command = s.clone(),
                    other => {
                        return Err(invalid_type(
                            other,
                            "a string",
                            Some(format!("{}.command", path)),
                        ))
                    }
                }
            }
            "description" => {
                if seen_description {
                    return Err(DeError {
                        msg: "duplicate field `description`".to_string(),
                        key: Some(path.clone()),
                    });
                }
                seen_description = true;
                match v {
                    Value::Str(s) => script.description = Some(s.clone()),
                    other => {
                        return Err(invalid_type(
                            other,
                            "a string",
                            Some(format!("{}.description", path)),
                        ))
                    }
                }
            }
            "tags" => {
                if seen_tags {
                    return Err(DeError {
                        msg: "duplicate field `tags`".to_string(),
                        key: Some(path.clone()),
                    });
                }
                seen_tags = true;
                match v {
                    Value::Array(items) => {
                        let mut tags = Vec::new();
                        for it in items {
                            match it {
                                Value::Str(s) => tags.push(s.clone()),
                                other => {
                                    return Err(invalid_type(
                                        other,
                                        "a string",
                                        Some(format!("{}.tags", path)),
                                    ))
                                }
                            }
                        }
                        script.tags = Some(tags);
                    }
                    other => {
                        return Err(invalid_type(
                            other,
                            "a sequence",
                            Some(format!("{}.tags", path)),
                        ))
                    }
                }
            }
            _ => {}
        }
    }
    if !seen_command {
        return Err(DeError {
            msg: "missing field `command`".to_string(),
            key: Some(path),
        });
    }
    Ok(script)
}

pub fn to_toml(cfg: &Config) -> String {
    let mut out = String::new();
    if cfg.scripts.is_empty() {
        out.push_str("[scripts]\n\n");
    } else {
        for (alias, s) in &cfg.scripts {
            out.push_str(&format!("[scripts.{}]\n", quote_key(alias)));
            out.push_str(&format!("command = {}\n", write_string(&s.command)));
            if let Some(d) = &s.description {
                out.push_str(&format!("description = {}\n", write_string(d)));
            }
            if let Some(t) = &s.tags {
                out.push_str(&format!("tags = {}\n", write_array(t)));
            }
            out.push('\n');
        }
    }
    out.push_str("[default]\n");
    if let Some(w) = cfg.default.command_width {
        out.push_str(&format!("command_width = {}\n", w));
    }
    out
}

fn write_array(items: &[String]) -> String {
    if items.len() <= 1 {
        let inner: Vec<String> = items.iter().map(|s| write_string(s)).collect();
        format!("[{}]", inner.join(", "))
    } else {
        let mut s = String::from("[\n");
        for it in items {
            s.push_str("    ");
            s.push_str(&write_string(it));
            s.push_str(",\n");
        }
        s.push(']');
        s
    }
}

// ---------------------------------------------------------------------------
// Config path resolution
// ---------------------------------------------------------------------------

pub fn config_dir() -> Option<std::path::PathBuf> {
    if let Some(v) = std::env::var_os("XDG_CONFIG_HOME") {
        let s = v.to_string_lossy().to_string();
        if !s.is_empty() {
            return Some(std::path::PathBuf::from(s));
        }
    }
    if let Some(h) = std::env::var_os("HOME") {
        let s = h.to_string_lossy().to_string();
        if !s.is_empty() {
            return Some(std::path::PathBuf::from(s).join(".config"));
        }
    }
    None
}

pub enum Resolved {
    Path(std::path::PathBuf),
    NotFound,
}

/// Resolve the config path the same way the original does: an explicit path
/// (`-c` / `$PIER_CONFIG_PATH`) is used as-is, otherwise the default chain is
/// searched for the first existing file.
pub fn resolve(explicit: Option<&std::path::PathBuf>) -> Resolved {
    if let Some(p) = explicit {
        return Resolved::Path(p.clone());
    }
    if let Some(v) = std::env::var_os("PIER_CONFIG_PATH") {
        // note: an empty value is still treated as "set"
        return Resolved::Path(std::path::PathBuf::from(v));
    }
    if let Ok(md) = std::env::current_dir() {
        let p = md.join("pier.toml");
        if p.is_file() {
            return Resolved::Path(p);
        }
    }
    if let Some(dir) = config_dir() {
        let p = dir.join("pier").join("config.toml");
        if p.is_file() {
            return Resolved::Path(p);
        }
        let p = dir.join("pier").join("config");
        if p.is_file() {
            return Resolved::Path(p);
        }
        let p = dir.join("pier.toml");
        if p.is_file() {
            return Resolved::Path(p);
        }
    }
    if let Some(h) = std::env::var_os("HOME") {
        let h = std::path::PathBuf::from(h);
        let p = h.join(".pier.toml");
        if p.is_file() {
            return Resolved::Path(p);
        }
        let p = h.join(".pier");
        if p.is_file() {
            return Resolved::Path(p);
        }
    }
    Resolved::NotFound
}

/// The path `config-init` writes to when nothing explicit is configured.
pub fn default_init_path() -> std::path::PathBuf {
    match config_dir() {
        Some(dir) => dir.join("pier").join("config.toml"),
        None => std::path::PathBuf::new(),
    }
}

pub fn read_config(path: &std::path::Path) -> Result<Config, String> {
    let contents = std::fs::read(path).map_err(|e| {
        format!("Unable to read config from file {}: {} ", path.display(), e)
    })?;
    let text = match String::from_utf8(contents) {
        Ok(t) => t,
        Err(_) => {
            return Err(format!(
                "Unable to read config from file {}: {} ",
                path.display(),
                "stream did not contain valid UTF-8"
            ))
        }
    };
    match parse(&text) {
        Ok(v) => match from_value(&v) {
            Ok(c) => Ok(c),
            Err(e) => Err(format!("Unable to parse toml config from file {}: {}", path.display(), e.to_display())),
        },
        Err(e) => Err(format!(
            "Unable to parse toml config from file {}: {}",
            path.display(),
            e.to_display()
        )),
    }
}

pub fn write_config(path: &std::path::Path, cfg: &Config) -> Result<(), String> {
    let text = to_toml(cfg);
    std::fs::write(path, text.as_bytes())
        .map_err(|e| format!("Unable to write config to {}: {}", path.display(), e))
}

pub fn default_config() -> Config {
    let mut cfg = Config::default();
    cfg.scripts.insert(
        "hello-pier".to_string(),
        Script {
            command: "echo Hello, Pier!".to_string(),
            description: Some("This is an example command.".to_string()),
            tags: None,
        },
    );
    cfg
}
