        || (0x2600..=0x27BF).contains(&cp)
}

pub fn display_width(s: &str) -> usize {
    s.chars().map(|c| char_width(c).max(0) as usize).sum()
}

/// Split into lines the same way Rust's `str::lines` does.
pub fn split_lines(s: &str) -> Vec<&str> {
    s.lines().collect()
}

pub fn pad_to(s: &str, width: usize) -> String {
    let w = display_width(s);
    let mut out = String::from(s);
    for _ in w..width {
        out.push(' ');
    }
    out
}

pub struct Table {
    pub headers: Vec<String>,
    pub rows: Vec<Vec<String>>,
}

impl Table {
    pub fn render(&self) -> String {
        let n = self.headers.len();
        let mut widths = vec![0usize; n];
        for (i, h) in self.headers.iter().enumerate() {
            widths[i] = display_width(h);
        }
        let mut prepared: Vec<Vec<Vec<&str>>> = Vec::new();
        for row in &self.rows {
            let mut cells: Vec<Vec<&str>> = Vec::new();
            for (i, c) in row.iter().enumerate() {
                let lines = split_lines(c);
                for l in &lines {
                    let w = display_width(l);
                    if w > widths[i] {
                        widths[i] = w;
                    }
                }
                cells.push(lines);
            }
            prepared.push(cells);
        }
        let total = 1 + widths.iter().map(|w| w + 2).sum::<usize>() + n;
        let border: String = std::iter::repeat('\u{2256}').take(total).collect();
        let sep = '\u{22EE}';

        let mut out = String::new();
        out.push_str(&border);
        out.push('\n');
        // header
        out.push_str(&render_row(
            &self.headers.iter().map(|s| vec![s.as_str()]).collect::<Vec<_>>(),
            &widths,
            sep,
        ));
        out.push_str(&border);
        out.push('\n');
        for cells in &prepared {
            out.push_str(&render_row(cells, &widths, sep));
        }
        out.push_str(&border);
        out.push('\n');
        out
    }
}

fn render_row(cells: &[Vec<&str>], widths: &[usize], sep: char) -> String {
    let mut height = 1usize;
    for c in cells {
        if c.len() > height {
            height = c.len();
        }
    }
    let mut out = String::new();
    for line in 0..height {
        out.push(sep);
        for (i, c) in cells.iter().enumerate() {
            let content = c.get(line).copied().unwrap_or("");
            out.push(' ');
            out.push_str(&pad_to(content, widths[i]));
            out.push(' ');
            out.push(sep);
        }
        out.push('\n');
    }
    out
}
