pub struct ArgDef {
    pub name: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub val_name: Option<&'static str>,
    pub multiple: bool,
    pub required: bool,
    pub positional: bool,
    pub last: bool,
    pub help: &'static str,
}

pub struct SubDef {
    pub name: &'static str,
    pub aliases: &'static [&'static str],
}

pub struct CmdDef {
    pub name: &'static str,
    pub app_title: &'static str, // used for the version line of the root command
    pub version: &'static str,
    pub author: Option<&'static str>,
    pub about: &'static str,
    pub next_line_help: bool,
    pub flags: Vec<ArgDef>,
    pub opts: Vec<ArgDef>,
    pub positionals: Vec<ArgDef>,
    pub flags_order: Vec<usize>,
    pub opts_order: Vec<usize>,
    pub pos_order: Vec<usize>,
    pub subcommands: Vec<SubDef>,
    pub usage: Vec<String>,
    pub required_order: Vec<usize>,
}

const HELP_HELP: &str = "Prints help information";
const VERSION_HELP: &str = "Prints version information";

fn help_arg() -> ArgDef {
    ArgDef {
        name: "help",
        short: Some('h'),
        long: Some("help"),
        val_name: None,
        multiple: false,
        required: false,
        positional: false,
        last: false,
        help: HELP_HELP,
    }
}
fn version_arg() -> ArgDef {
    ArgDef {
        name: "version",
        short: Some('V'),
        long: Some("version"),
        val_name: None,
        multiple: false,
        required: false,
        positional: false,
        last: false,
        help: VERSION_HELP,
    }
}

fn a(
    name: &'static str,
    short: Option<char>,
    long: Option<&'static str>,
    val_name: Option<&'static str>,
    multiple: bool,
    required: bool,
    positional: bool,
    last: bool,
    help: &'static str,
) -> ArgDef {
    ArgDef { name, short, long, val_name, multiple, required, positional, last, help }
}

const ROOT_ABOUT: &str = "A simple script management CLI";
const CONFIG_LONG_HELP: &str = "Sets a custom config file.\n\nDEFAULT PATH is otherwise determined in this order:\n\n- $PIER_CONFIG_PATH (environment variable if set)\n\n- pier.toml (in the current directory)\n\n- $XDG_CONFIG_HOME/pier/config.toml\n\n- $XDG_CONFIG_HOME/pier/config\n\n- $XDG_CONFIG_HOME/pier.toml\n\n- $HOME/.pier.toml\n\n- $HOME/.pier\n";

const LIST_ABOUT: &str = "alias: ls - List scripts\n\nDisplay options are determined by priority in this order:\n\n1. List only aliases\n\n2. Show full command\n\n3. Command display with (cli option)\n\n4. Command display with (config option)";

pub fn build_root() -> CmdDef {
    let flags = vec![a(
        "verbose",
        Some('v'),
        Some("verbose"),
        None,
        false,
        false,
        false,
        false,
        "The level of verbosity",
    )];
    let opts = vec![a(
        "config-file",
        Some('c'),
        Some("config-file"),
        Some("path"),
        false,
        false,
        false,
        false,
        "Sets a custom config file",
    )];
    let positionals = vec![
        a("alias", None, None, None, false, true, true, false, "The alias or name for the script."),
        a(
            "args",
            None,
            None,
            None,
            true,
            false,
            true,
            true,
            "The positional arguments to send to script.",
        ),
    ];
    let subcommands = vec![
        SubDef { name: "add", aliases: &[] },
        SubDef { name: "config-init", aliases: &["init"] },
        SubDef { name: "copy", aliases: &["cp"] },
        SubDef { name: "edit", aliases: &[] },
        SubDef { name: "help", aliases: &[] },
        SubDef { name: "list", aliases: &["ls"] },
        SubDef { name: "move", aliases: &["mv", "rename"] },
        SubDef { name: "remove", aliases: &["rm"] },
        SubDef { name: "run", aliases: &[] },
        SubDef { name: "show", aliases: &[] },
    ];
    let usage = vec![
        "{bin} [FLAGS] [OPTIONS] <alias> [args]...".to_string(),
        "{bin} [FLAGS] [OPTIONS] <SUBCOMMAND>".to_string(),
    ];
    let mut auto = vec![help_arg(), version_arg()];
    let mut all_flags = Vec::new();
    all_flags.extend(auto.drain(..));
    all_flags.extend(flags);
    CmdDef {
        name: "pier",
        app_title: "pier",
        version: "0.1.6",
        author: Some("Benjamin Scholtz, Isak Johansson"),
        about: ROOT_ABOUT,
        next_line_help: true,
        flags: all_flags,
        opts,
        positionals,
        flags_order: vec![0, 1, 2],
        opts_order: vec![0],
        pos_order: vec![0, 1],
        subcommands,
        usage,
        required_order: vec![0],
    }
}

pub fn build_sub(name: &str) -> Option<CmdDef> {
    let (flags, opts, positionals, about, flags_order, opts_order, pos_order, required_order, usage, nlh): (
        Vec<ArgDef>,
        Vec<ArgDef>,
        Vec<ArgDef>,
        &'static str,
        Vec<usize>,
        Vec<usize>,
        Vec<usize>,
        Vec<usize>,
        Vec<String>,
        bool,
    ) = match name {
        "add" => (
            vec![a(
                "force",
                Some('f'),
                Some("force"),
                None,
                false,
                false,
                false,
                false,
                "Allows to overwrite the existing script",
            )],
            vec![
                a("alias", Some('a'), Some("alias"), Some("alias"), false, true, false, false, "The alias or name for the script."),
                a("description", Some('d'), Some("description"), Some("description"), false, false, false, false, "The description for the script."),
                a("tag", Some('t'), Some("tag"), Some("tags"), true, false, false, false, "Set which tags the script belongs to."),
            ],
            vec![a(
                "command",
                None,
                None,
                None,
                false,
                false,
                true,
                false,
                "The command/script content to be executed. If this argument is not found it will open your $EDITOR for you to enter the script into.",
            )],
            "Add a new script to config.",
            vec![0, 1, 2],
            vec![0, 1, 2],
            vec![0],
            vec![0],
            vec!["{bin} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]".to_string()],
            false,
        ),
        "config-init" => (
            vec![],
            vec![],
            vec![],
            "alias: init - Add a config file.",
            vec![0, 1],
            vec![],
            vec![],
            vec![],
            vec!["{bin} config-init".to_string()],
            false,
        ),
        "copy" => (
            vec![],
            vec![],
            vec![
                a("from-alias", None, None, None, false, true, true, false, "The alias of the script that will be copied."),
                a("to-alias", None, None, None, false, true, true, false, "The new alias of the copy of the script."),
            ],
            "alias: cp - Copy existing alias to the new one",
            vec![0, 1],
            vec![],
            vec![0, 1],
            vec![0, 1],
            vec!["{bin} copy <from-alias> <to-alias>".to_string()],
            false,
        ),
        "edit" => (
            vec![],
            vec![],
            vec![a("alias", None, None, None, false, true, true, false, "The alias or name for the script.")],
            "Edit a script matching alias.",
            vec![0, 1],
            vec![],
            vec![0],
            vec![0],
            vec!["{bin} edit <alias>".to_string()],
            false,
        ),
        "list" => (
            vec![
                a("cmd_full", Some('l'), Some("cmd_full"), None, false, false, false, false, "Display the full command."),
                a("list_aliases", Some('q'), Some("list_aliases"), None, false, false, false, false, "Only displays aliases of the scripts."),
            ],
            vec![
                a("cmd_width", Some('c'), Some("cmd_width"), Some("cmd-width"), false, false, false, false, "The max number of characters to display from the command."),
                a("tag", Some('t'), Some("tag"), Some("tags"), true, false, false, false, "Filter based on tags."),
            ],
            vec![],
            LIST_ABOUT,
            vec![0, 1, 2, 3],
            vec![0, 1],
            vec![],
            vec![],
            vec!["{bin} list [FLAGS] [OPTIONS]".to_string()],
            true,
        ),
        "move" => (
            vec![a(
                "force",
                Some('f'),
                Some("force"),
                None,
                false,
                false,
                false,
                false,
                "Allows to overwrite the existing script",
            )],
            vec![],
            vec![
                a("from-alias", None, None, None, false, true, true, false, "The alias of the script that will be moved."),
                a("to-alias", None, None, None, false, true, true, false, "The new alias of the script."),
            ],
            "alias: mv, rename - Move/rename existing alias to the new one",
            vec![0, 1, 2],
            vec![],
            vec![0, 1],
            vec![0, 1],
            vec!["{bin} move [FLAGS] <from-alias> <to-alias>".to_string()],
            false,
        ),
        "remove" => (
            vec![],
            vec![],
            vec![a("alias", None, None, None, false, true, true, false, "The alias or name for the script.")],
            "alias: rm - Remove a script matching alias.",
            vec![0, 1],
            vec![],
            vec![0],
            vec![0],
            vec!["{bin} remove <alias>".to_string()],
            false,
        ),
        "run" => (
            vec![],
            vec![],
            vec![
                a("alias", None, None, None, false, true, true, false, "The alias or name for the script."),
                a("args", None, None, None, true, false, true, false, "The positional arguments to send to script."),
            ],
            "Run a script matching alias.",
            vec![0, 1],
            vec![],
            vec![0, 1],
            vec![0],
            vec!["{bin} run <alias> [args]...".to_string()],
            false,
        ),
        "show" => (
            vec![],
            vec![],
            vec![a("alias", None, None, None, false, true, true, false, "The alias or name for the script.")],
            "Show a script matching alias.",
            vec![0, 1],
            vec![],
            vec![0],
            vec![0],
            vec!["{bin} show <alias>".to_string()],
            false,
        ),
        "help" => (
            vec![],
            vec![],
            vec![a(
                "subcommand",
                None,
                None,
                None,
                true,
                false,
                true,
                false,
                "The subcommand whose help message to display",
            )],
            "Prints this message or the help of the given subcommand(s)",
            vec![],
            vec![],
            vec![0],
            vec![],
            vec!["{bin} help [subcommand]...".to_string()],
            false,
        ),
        _ => return None,
    };
    let mut all_flags = vec![help_arg(), version_arg()];
    all_flags.extend(flags);
    let off = all_flags.len();
    let fo: Vec<usize> = flags_order.iter().map(|i| i + off).collect();
    let nopts = opts.len();
    let oo: Vec<usize> = opts_order.iter().map(|i| *i).collect();
    let po: Vec<usize> = pos_order.iter().map(|i| *i).collect();
    let ro: Vec<usize> = required_order.iter().map(|i| *i).collect();
    let _ = nopts;
    Some(CmdDef {
        name,
        app_title: "",
        version: "0.1.6",
        author: None,
        about,
        next_line_help: nlh,
        flags: all_flags,
        opts,
        positionals,
        flags_order: fo,
        opts_order: oo,
        pos_order: po,
        subcommands: Vec::new(),
        usage,
        required_order: ro,
    })
}

pub fn build_help_sub() -> CmdDef {
    // the auto generated `help` sub command has no version
    let mut c = build_sub("help").unwrap();
    c.version = "";
    c
}

// ---------------------------------------------------------------------------
// rendering helpers
// ---------------------------------------------------------------------------

pub fn arg_display(x: &ArgDef) -> String {
    if x.positional {
        let mut s = format!("<{}>", x.name);
        if x.multiple {
            s.push_str("...");
        }
        s
    } else {
        let mut s = String::new();
        if let Some(c) = x.short {
            s.push_str(&format!("-{}, ", c));
        }
        s.push_str(&format!("--{}", x.long.unwrap_or(x.name)));
        if let Some(v) = x.val_name {
            s.push_str(&format!(" <{}>", v));
            if x.multiple {
                s.push_str("...");
            }
        }
        s
    }
}

pub fn arg_usage(x: &ArgDef) -> String {
    if x.positional {
        let mut s = format!("<{}>", x.name);
        if x.multiple {
            s.push_str("...");
        }
        s
    } else {
        let mut s = format!("--{}", x.long.unwrap_or(x.name));
        if let Some(v) = x.val_name {
            s.push_str(&format!(" <{}>", v));
            if x.multiple {
                s.push_str("...");
            }
        }
        s
    }
}

fn find_arg<'a>(c: &'a CmdDef, name: &str) -> Option<&'a ArgDef> {
    c.flags
        .iter()
        .chain(c.opts.iter())
        .chain(c.positionals.iter())
        .find(|a| a.name == name)
}

fn display_width(s: &str) -> usize {
    crate::table::display_width(s)
}

fn wrap_line(line: &str, width: usize) -> Vec<String> {
    if display_width(line) <= width {
        return vec![line.to_string()];
    }
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut cur_w = 0usize;
    let mut first = true;
    let mut iter = line.chars().peekable();
    // split into words preserving the leading whitespace of the line
    let mut words: Vec<(String, String)> = Vec::new(); // (word, trailing spaces)
    let mut lead = String::new();
    while let Some(&c) = iter.peek() {
        if c == ' ' {
            lead.push(c);
            iter.next();
        } else {
            break;
        }
    }
    let mut word = String::new();
    let mut trail = String::new();
    for c in line.chars().skip(lead.chars().count()) {
        if c == ' ' {
            if !word.is_empty() {
                words.push((std::mem::replace(&mut word, String::new()), String::new()));
            }
            trail.push(' ');
        } else {
            if !trail.is_empty() {
                // attach the pending whitespace to the current word start
                word.push_str(&trail);
                trail.clear();
            }
            word.push(c);
        }
    }
    if !word.is_empty() {
        words.push((word, String::new()));
    }
    let _ = trail;
    for (w, _t) in words {
        let ww = display_width(&w);
        if first {
            cur = w.clone();
            cur_w = ww;
            first = false;
        } else if cur_w + 1 + ww <= width {
            cur.push(' ');
            cur.push_str(&w);
            cur_w += 1 + ww;
        } else {
            out.push(std::mem::replace(&mut cur, String::new()));
            cur = w.clone();
            cur_w = ww;
        }
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    if out.is_empty() {
        out.push(String::new());
    }
    out
}

pub struct HelpCtx {
    pub bin: String,
    pub env_val: String,
}

pub fn render_help(c: &CmdDef, ctx: &HelpCtx, long: bool) -> String {
    let mut lines: Vec<String> = Vec::new();
    // version line
    if c.name == "pier" {
        lines.push(format!("{} {}", c.app_title, c.version));
    } else {
        lines.push(format!("{}-{} {}", ctx.bin, c.name, c.version));
    }
    if let Some(au) = c.author {
        lines.push(au.to_string());
    }
    for l in c.about.split('\n') {
        lines.push(l.to_string());
    }
    lines.push(String::new());
    lines.push("USAGE:".to_string());
    for u in &c.usage {
        lines.push(format!("    {}", u.replace("{bin}", &ctx.bin)));
    }
    let term_w = 120usize;

    let mut sections: Vec<(&str, Vec<usize>, fn(&ArgDef) -> String)> = Vec::new();
    if !c.flags_order.is_empty() {
        sections.push(("FLAGS", c.flags_order.clone(), |a| arg_display(a)));
    }
    if !c.opts_order.is_empty() {
        sections.push(("OPTIONS", c.opts_order.clone(), |a| arg_display(a)));
    }
    if !c.pos_order.is_empty() {
        sections.push(("ARGS", c.pos_order.clone(), |a| arg_display(a)));
    }
    if !c.subcommands.is_empty() {
        // handled separately
    }

    for (si, (title, order, disp)) in sections.iter().enumerate() {
        lines.push(String::new());
        lines.push(format!("{}:", title));
        let args: Vec<&ArgDef> = order.iter().map(|i| pick_arg(c, *i)).collect();
        let longest = args.iter().map(|a| display_width(&disp(a))).max().unwrap_or(2);
        let longest = if longest < 2 { 2 } else { longest };
        // width used for the wrap calculation: clap uses the `--long` form
        let longest_usage = args
            .iter()
            .map(|a| display_width(&arg_usage(a)))
            .max()
            .unwrap_or(2);
        let spcs = longest_usage + 12;
        for (ai, arg) in args.iter().enumerate() {
            if ai > 0 {
                lines.push(String::new());
            }
            let disp_s = disp(arg);
            let mut aline = String::from("    ");
            let padded = crate::table::pad_to(&disp_s, longest);
            aline.push_str(&padded);
            aline.push_str("    ");
            let nlh = long && c.next_line_help;
            let help_text = arg_help_text(arg, ctx, long);
            if nlh {
                lines.push(aline);
                let wrapped = if spcs + max_line_len(&help_text) > term_w {
                    help_text
                        .split('\n')
                        .flat_map(|l| wrap_line(l, term_w - spcs))
                        .collect::<Vec<_>>()
                } else {
                    help_text.split('\n').map(|s| s.to_string()).collect()
                };
                for wl in wrapped {
                    lines.push(format!("            {}", wl));
                }
                if !help_text.contains('\n') {
                    // clap emits a trailing newline for single line helps
                    // (represented as an extra blank line by the section logic)
                    lines.push(String::new());
                }
            } else {
                let wrapped = if spcs + max_line_len(&help_text) > term_w {
                    let w = wrap_line(&help_text, term_w - spcs);
                    // first line goes on the arg line
                    let mut it = w.into_iter();
                    let firstl = it.next().unwrap_or_default();
                    let mut l = aline.clone();
                    l.push_str(&firstl);
                    lines.push(l);
                    for rest in it {
                        lines.push(format!("{}{}", " ".repeat(4 + longest + 4), rest));
                    }
                    continue;
                } else {
                    vec![help_text.clone()]
                };
                let mut l = aline.clone();
                l.push_str(&wrapped[0]);
                lines.push(l);
                for rest in wrapped.iter().skip(1) {
                    lines.push(format!("{}{}", " ".repeat(4 + longest + 4), rest));
                }
            }
        }
        if si + 1 < sections.len() + if c.subcommands.is_empty() { 0 } else { 1 } {
            lines.push(String::new());
            // clap adds an extra blank line when the previous help had no newline
        }
    }

    if !c.subcommands.is_empty() {
        lines.push(String::new());
        lines.push("SUBCOMMANDS:".to_string());
        let names: Vec<&SubDef> = c.subcommands.iter().collect();
        let longest = names.iter().map(|s| display_width(s.name)).max().unwrap_or(2);
        for (i, s) in names.iter().enumerate() {
            let about = sub_about(c, s.name);
            let aline = format!(
                "    {}    ",
                crate::table::pad_to(s.name, longest)
            );
            if i == 0 {
                lines.push(aline + &about);
            } else {
                lines.push(aline + &about);
            }
        }
    }
    let mut out = lines.join("\n");
    out.push('\n');
    out
}

fn pick_arg(c: &CmdDef, i: usize) -> &ArgDef {
    if i < c.flags.len() {
        &c.flags[i]
    } else if i < c.flags.len() + c.opts.len() {
        &c.opts[i - c.flags.len()]
    } else {
        &c.positionals[i - c.flags.len() - c.opts.len()]
    }
}

fn arg_help_text(arg: &ArgDef, ctx: &HelpCtx, long: bool) -> String {
    let mut h = arg.help.to_string();
    if let Some(env) = arg.env {
        if arg.name == "config-file" {
            if long {
                h = crate::cli_longhelp::config_long_help(&ctx.env_val);
            } else {
                h = format!("{} [env: {}={}]", h, env, ctx.env_val);
            }
        }
    }
    h
}

fn max_line_len(s: &str) -> usize {
    s.split('\n').map(|l| display_width(l)).max().unwrap_or(0)
}

fn sub_about(c: &CmdDef, name: &str) -> String {
    // about texts for the root command's sub commands
    match name {
        "add" => "Add a new script to config.".to_string(),
        "config-init" => "alias: init - Add a config file.".to_string(),
        "copy" => "alias: cp - Copy existing alias to the new one".to_string(),
        "edit" => "Edit a script matching alias.".to_string(),
        "help" => "Prints this message or the help of the given subcommand(s)".to_string(),
        "list" => crate::cli_longhelp::LIST_ABOUT_FIRST.to_string(),
        "move" => "alias: mv, rename - Move/rename existing alias to the new one".to_string(),
        "remove" => "alias: rm - Remove a script matching alias.".to_string(),
        "run" => "Run a script matching alias.".to_string(),
        "show" => "Show a script matching alias.".to_string(),
        _ => String::new(),
    }
}
