fn dw(s: &str) -> usize {
    crate::table::display_width(s)
}

/// textwrap-like greedy fill that never breaks words.
fn wrap_line(line: &str, width: usize) -> Vec<String> {
    if dw(line) <= width {
        return vec![line.to_string()];
    }
    let mut words: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut started = false;
    for ch in line.chars() {
        if ch == ' ' {
            if started {
                words.push(std::mem::replace(&mut cur, String::new()));
                started = false;
            } else if words.is_empty() && cur.is_empty() {
                // leading whitespace is kept with the first word
                cur.push(' ');
            } else {
                cur.push(' ');
            }
        } else {
            started = true;
            cur.push(ch);
        }
    }
    if !cur.is_empty() {
        words.push(cur);
    }
    let mut out: Vec<String> = Vec::new();
    let mut line_buf = String::new();
    let mut lw = 0usize;
    for w in words {
        let ww = dw(&w);
        if lw == 0 {
            line_buf = w.clone();
            lw = ww;
        } else if lw + 1 + ww <= width {
            line_buf.push(' ');
            line_buf.push_str(&w);
            lw += 1 + ww;
        } else {
            out.push(std::mem::replace(&mut line_buf, String::new()));
            line_buf = w.clone();
            lw = ww;
        }
    }
    if !line_buf.is_empty() {
        out.push(line_buf);
    }
    if out.is_empty() {
        out.push(String::new());
    }
    out
}

fn max_line_len(s: &str) -> usize {
    s.split('\n').map(|l| dw(l)).max().unwrap_or(0)
}

pub struct HelpCtx {
    pub bin: String,
    pub env_val: String,
}

fn config_help(env_val: &str, long: bool) -> String {
    if long {
        let base = "Sets a custom config file.\n\nDEFAULT PATH is otherwise determined in this order:\n\n- $PIER_CONFIG_PATH (environment variable if set)\n\n- pier.toml (in the current directory)\n\n- $XDG_CONFIG_HOME/pier/config.toml\n\n- $XDG_CONFIG_HOME/pier/config\n\n- $XDG_CONFIG_HOME/pier.toml\n\n- $HOME/.pier.toml\n\n- $HOME/.pier\n";
        format!("{}\n [env: PIER_CONFIG_PATH={}]", base, env_val)
    } else {
        format!("Sets a custom config file [env: PIER_CONFIG_PATH={}]", env_val)
    }
}

fn arg_help(x: &ArgDef, ctx: &HelpCtx, long: bool) -> String {
    if x.name == "config-file" {
        config_help(&ctx.env_val, long)
    } else {
        x.help.to_string()
    }
}

pub fn render_help(c: &CmdDef, ctx: &HelpCtx, long: bool) -> String {
    let mut lines: Vec<String> = Vec::new();
    if c.name == "pier" {
        lines.push(format!("pier {}", c.version));
    } else {
        lines.push(format!("{}-{} {}", ctx.bin, c.name, c.version));
    }
    if let Some(au) = c.author {
        lines.push(au.to_string());
    }
    for l in c.about.split('\n') {
        lines.push(l.to_string());
    }
    lines.push(String::new());
    lines.push("USAGE:".to_string());
    for u in &c.usage {
        lines.push(format!("    {}", u.replace("{bin}", &ctx.bin)));
    }

    let term_w = 120usize;
    let mut sections: Vec<(&'static str, Vec<&ArgDef>)> = Vec::new();
    let fo: Vec<&ArgDef> = c.flags_order.iter().map(|n| find_arg(c, n).unwrap()).collect();
    if !fo.is_empty() {
        sections.push(("FLAGS", fo));
    }
    let oo: Vec<&ArgDef> = c.opts_order.iter().map(|n| find_arg(c, n).unwrap()).collect();
    if !oo.is_empty() {
        sections.push(("OPTIONS", oo));
    }
    let po: Vec<&ArgDef> = c.pos_order.iter().map(|n| find_arg(c, n).unwrap()).collect();
    if !po.is_empty() {
        sections.push(("ARGS", po));
    }

    let nlh_mode = long && c.next_line_help;
    for (si, (title, args)) in sections.iter().enumerate() {
        lines.push(String::new());
        lines.push(format!("{}:", title));
        let longest = args.iter().map(|a| dw(&arg_display(a))).max().unwrap_or(2).max(2);
        let longest_usage = args.iter().map(|a| dw(&arg_usage(a))).max().unwrap_or(2).max(2);
        let spcs = longest_usage + 12;
        let col = 4 + longest + 4;
        let mut last_single = false;
        for (ai, arg) in args.iter().enumerate() {
            if ai > 0 {
                lines.push(String::new());
            }
            let disp_s = arg_display(arg);
            let aline = format!("    {}    ", crate::table::pad_to(&disp_s, longest));
            let help_text = arg_help(arg, ctx, long);
            last_single = !help_text.contains('\n');
            if nlh_mode {
                lines.push(aline);
                let wrapped: Vec<String> =
                    if spcs + max_line_len(&help_text) > term_w {
                        help_text
                            .split('\n')
                            .flat_map(|l| wrap_line(l, term_w - spcs))
                            .collect()
                    } else {
                        help_text.split('\n').map(|s| s.to_string()).collect()
                    };
                for wl in wrapped {
                    lines.push(format!("            {}", wl));
                }
                if last_single {
                    lines.push(String::new());
                }
            } else {
                let wrapped: Vec<String> = if spcs + max_line_len(&help_text) > term_w {
                    wrap_line(&help_text, term_w - spcs)
                } else {
                    vec![help_text.clone()]
                };
                let mut first = true;
                for wl in wrapped {
                    if first {
                        let mut l = aline.clone();
                        l.push_str(&wl);
                        lines.push(l);
                        first = false;
                    } else {
                        lines.push(format!("{}{}", " ".repeat(col), wl));
                    }
                }
            }
        }
        let _ = si;
    }

    if !c.subcommands.is_empty() {
        lines.push(String::new());
        lines.push("SUBCOMMANDS:".to_string());
        let longest = c
            .subcommands
            .iter()
            .map(|s| dw(s.name))
            .max()
            .unwrap_or(2)
            .max(2);
        for s in &c.subcommands {
            let about = sub_about(s.name);
            lines.push(format!(
                "    {}    {}",
                crate::table::pad_to(s.name, longest),
                about
            ));
        }
    }
    let mut out = lines.join("\n");
    out.push('\n');
    out
}

fn sub_about(name: &str) -> String {
    match name {
        "add" => "Add a new script to config.",
        "config-init" => "alias: init - Add a config file.",
        "copy" => "alias: cp - Copy existing alias to the new one",
        "edit" => "Edit a script matching alias.",
        "help" => "Prints this message or the help of the given subcommand(s)",
        "list" => "alias: ls - List scripts",
        "move" => "alias: mv, rename - Move/rename existing alias to the new one",
        "remove" => "alias: rm - Remove a script matching alias.",
        "run" => "Run a script matching alias.",
        "show" => "Show a script matching alias.",
        _ => "",
    }
    .to_string()
}
RSEOF
echo ok"}

