// Hand written re-implementation of the clap 2.x command line handling used by
// the original program: argument parsing, help rendering and error messages.

pub struct ArgDef {
    pub name: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub val_name: Option<&'static str>,
    pub multiple: bool,
    pub required: bool,
    pub positional: bool,
    pub last: bool,
    pub help: &'static str,
}

pub struct SubDef {
    pub name: &'static str,
    pub aliases: &'static [&'static str],
}

pub struct CmdDef {
    pub name: &'static str,
    pub version: &'static str,
    pub author: Option<&'static str>,
    pub about: &'static str,
    pub next_line_help: bool,
    pub args: Vec<ArgDef>, // flags ++ opts ++ positionals
    pub flags_order: Vec<&'static str>,
    pub opts_order: Vec<&'static str>,
    pub pos_order: Vec<&'static str>,
