    }
}
fn version_arg() -> ArgDef {
    ArgDef {
        name: "version",
        short: Some('V'),
        long: Some("version"),
        val_name: None,
        multiple: false,
        required: false,
        positional: false,
        last: false,
        help: VERSION_HELP,
    }
}

#[allow(clippy::too_many_arguments)]
fn a(
    name: &'static str,
    short: Option<char>,
    long: Option<&'static str>,
    val_name: Option<&'static str>,
    multiple: bool,
    required: bool,
    positional: bool,
    last: bool,
    help: &'static str,
) -> ArgDef {
    ArgDef { name, short, long, val_name, multiple, required, positional, last, help }
}

const ROOT_ABOUT: &str = "A simple script management CLI";
const LIST_ABOUT: &str = "alias: ls - List scripts\n\nDisplay options are determined by priority in this order:\n\n1. List only aliases\n\n2. Show full command\n\n3. Command display with (cli option)\n\n4. Command display with (config option)";

fn force_arg() -> ArgDef {
    a(
        "force",
        Some('f'),
        Some("force"),
        None,
        false,
        false,
        false,
        false,
