pub fn build_sub(name: &str) -> Option<CmdDef> {
    let mut args: Vec<ArgDef> = Vec::new();
    let mut flags_order: Vec<&'static str> = Vec::new();
    let mut opts_order: Vec<&'static str> = Vec::new();
    let mut pos_order: Vec<&'static str> = Vec::new();
    let usage: Vec<&'static str>;
    let about: &'static str;
    let nlh: bool;
    match name {
        "add" => {
            args.push(force_arg());
            flags_order.push("force");
            args.push(a("alias", Some('a'), Some("alias"), Some("alias"), false, true, false, false, "The alias or name for the script."));
            opts_order.push("alias");
            args.push(a("description", Some('d'), Some("description"), Some("description"), false, false, false, false, "The description for the script."));
            opts_order.push("description");
            args.push(tag_opt());
            opts_order.push("tag");
            args.push(a("command", None, None, None, false, false, true, false, "The command/script content to be executed. If this argument is not found it will open your $EDITOR for you to enter the script into."));
            pos_order.push("command");
            about = "Add a new script to config.";
            usage = vec!["{bin} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]"];
            nlh = false;
        }
        "config-init" => {
            about = "alias: init - Add a config file.";
            usage = vec!["{bin} config-init"];
            nlh = false;
        }
        "copy" => {
            args.push(a("from-alias", None, None, None, false, true, true, false, "The alias of the script that will be copied."));
            args.push(a("to-alias", None, None, None, false, true, true, false, "The new alias of the copy of the script."));
            pos_order.push("from-alias");
            pos_order.push("to-alias");
            about = "alias: cp - Copy existing alias to the new one";
            usage = vec!["{bin} copy <from-alias> <to-alias>"];
            nlh = false;
        }
        "edit" => {
            args.push(alias_pos());
            pos_order.push("alias");
            about = "Edit a script matching alias.";
            usage = vec!["{bin} edit <alias>"];
            nlh = false;
        }
        "list" => {
            args.push(a("cmd_full", Some('l'), Some("cmd_full"), None, false, false, false, false, "Display the full command."));
            flags_order.push("cmd_full");
            args.push(a("list_aliases", Some('q'), Some("list_aliases"), None, false, false, false, false, "Only displays aliases of the scripts."));
            flags_order.push("list_aliases");
            args.push(a("cmd_width", Some('c'), Some("cmd_width"), Some("cmd-width"), false, false, false, false, "The max number of characters to display from the command."));
            opts_order.push("cmd_width");
            args.push(tags_opt());
            opts_order.push("tag");
            about = LIST_ABOUT;
            usage = vec!["{bin} list [FLAGS] [OPTIONS]"];
            nlh = true;
        }
        "move" => {
            args.push(force_arg());
            flags_order.push("force");
            args.push(a("from-alias", None, None, None, false, true, true, false, "The alias of the script that will be moved."));
            args.push(a("to-alias", None, None, None, false, true, true, false, "The new alias of the script."));
            pos_order.push("from-alias");
            pos_order.push("to-alias");
            about = "alias: mv, rename - Move/rename existing alias to the new one";
            usage = vec!["{bin} move [FLAGS] <from-alias> <to-alias>"];
            nlh = false;
        }
        "remove" => {
            args.push(alias_pos());
            pos_order.push("alias");
            about = "alias: rm - Remove a script matching alias.";
            usage = vec!["{bin} remove <alias>"];
            nlh = false;
        }
        "run" => {
            args.push(alias_pos());
            args.push(a("args", None, None, None, true, false, true, false, "The positional arguments to send to script."));
            pos_order.push("alias");
            pos_order.push("args");
            about = "Run a script matching alias.";
            usage = vec!["{bin} run <alias> [args]..."];
            nlh = false;
        }
        "show" => {
            args.push(alias_pos());
            pos_order.push("alias");
            about = "Show a script matching alias.";
            usage = vec!["{bin} show <alias>"];
            nlh = false;
        }
        "help" => {
            args.push(a("subcommand", None, None, None, true, false, true, false, "The subcommand whose help message to display"));
            pos_order.push("subcommand");
            about = "Prints this message or the help of the given subcommand(s)";
            usage = vec!["{bin} help [subcommand]..."];
            nlh = false;
        }
        _ => return None,
    }
    args.push(help_arg());
    flags_order.push("help");
    args.push(version_arg());
    flags_order.push("version");
    Some(CmdDef {
        name,
        version: "0.1.6",
        author: None,
        about,
        next_line_help: nlh,
        args,
        flags_order,
        opts_order,
        pos_order,
        subcommands: Vec::new(),
        usage,
    })
}

pub fn build_help_sub() -> CmdDef {
    let mut c = build_sub("help").unwrap();
    c.version = "";
    c
}

pub fn find_arg<'a>(c: &'a CmdDef, name: &str) -> Option<&'a ArgDef> {
    c.args.iter().find(|a| a.name == name)
}

pub fn arg_display(x: &ArgDef) -> String {
    if x.positional {
        let mut s = format!("<{}>", x.name);
        if x.multiple {
            s.push_str("...");
        }
        s
    } else {
        let mut s = String::new();
        if let Some(ch) = x.short {
            s.push_str(&format!("-{}, ", ch));
        }
        s.push_str(&format!("--{}", x.long.unwrap_or(x.name)));
        if let Some(v) = x.val_name {
            s.push_str(&format!(" <{}>", v));
            if x.multiple {
                s.push_str("...");
            }
        }
        s
    }
}

pub fn arg_usage(x: &ArgDef) -> String {
    if x.positional {
        let mut s = format!("<{}>", x.name);
        if x.multiple {
            s.push_str("...");
        }
        s
    } else {
        let mut s = format!("--{}", x.long.unwrap_or(x.name));
        if let Some(v) = x.val_name {
            s.push_str(&format!(" <{}>", v));
            if x.multiple {
                s.push_str("...");
            }
        }
        s
    }
}

fn dw(s: &str) -> usize {
    crate::table::display_width(s)
}

/// textwrap-like greedy fill that never breaks words.
fn wrap_line(line: &str, width: usize) -> Vec<String> {
    if dw(line) <= width {
        return vec![line.to_string()];
    }
    let mut words: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut started = false;
    for ch in line.chars() {
        if ch == ' ' {
            if started {
                words.push(std::mem::replace(&mut cur, String::new()));
                started = false;
            } else if words.is_empty() && cur.is_empty() {
                // leading whitespace is kept with the first word
                cur.push(' ');
            } else {
                cur.push(' ');
            }
        } else {
            started = true;
            cur.push(ch);
        }
    }
    if !cur.is_empty() {
        words.push(cur);
    }
    let mut out: Vec<String> = Vec::new();
    let mut line_buf = String::new();
    let mut lw = 0usize;
    for w in words {
        let ww = dw(&w);
        if lw == 0 {
            line_buf = w.clone();
            lw = ww;
        } else if lw + 1 + ww <= width {
            line_buf.push(' ');
            line_buf.push_str(&w);
            lw += 1 + ww;
        } else {
            out.push(std::mem::replace(&mut line_buf, String::new()));
            line_buf = w.clone();
            lw = ww;
        }
    }
    if !line_buf.is_empty() {
        out.push(line_buf);
    }
    if out.is_empty() {
        out.push(String::new());
    }
    out
}

fn max_line_len(s: &str) -> usize {
    s.split('\n').map(|l| dw(l)).max().unwrap_or(0)
}

