// clap 2.x compatible argument parsing.

use crate::cli::*;
use std::collections::HashMap;

#[derive(Default)]
pub struct Matches {
    pub vals: HashMap<String, Vec<String>>,
    pub occ: HashMap<String, usize>,
    pub used: Vec<String>, // names of non-positional args, insertion order
}

impl Matches {
    fn add_val(&mut self, name: &str, v: String) {
        self.vals.entry(name.to_string()).or_default().push(v);
        if !self.used.contains(&name.to_string()) {
            self.used.push(name.to_string());
        }
    }
    fn add_occ(&mut self, name: &str) {
        *self.occ.entry(name.to_string()).or_insert(0) += 1;
        if !self.used.contains(&name.to_string()) {
            self.used.push(name.to_string());
        }
    }
    pub fn value_of(&self, name: &str) -> Option<&str> {
        self.vals.get(name).and_then(|v| v.first()).map(|s| s.as_str())
    }
    pub fn values_of(&self, name: &str) -> Vec<String> {
        self.vals.get(name).cloned().unwrap_or_default()
    }
    pub fn is_present(&self, name: &str) -> bool {
        self.occ.contains_key(name)
    }
    pub fn occurrences_of(&self, name: &str) -> usize {
        *self.occ.get(name).unwrap_or(&0)
    }
}

pub enum ClapError {
    UnknownArg { arg: String, usage: String },
    MissingRequired { args: Vec<String>, usage: String },
    EmptyValue { arg: String, usage: String },
    InvalidValue { arg: String, val: String, err: String },
    MultipleOccurrence { arg: String, usage: String },
    InvalidSubcommand { sub: String, dym: String, bin: String, usage: String },
    UnrecognizedSubcommand { sub: String, bin: String },
    DisplayHelp(String),
    DisplayVersion(String),
}

impl ClapError {
    pub fn render(&self) -> String {
        match self {
            ClapError::UnknownArg { arg, usage } => format!(
                "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                arg, usage
            ),
            ClapError::MissingRequired { args, usage } => {
                let mut s = String::from("error: The following required arguments were not provided:\n");
                for a in args {
                    s.push_str(&format!("    {}\n", a));
                }
                s.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try --help\n", usage));
                s
            }
            ClapError::EmptyValue { arg, usage } => format!(
                "error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                arg, usage
            ),
            ClapError::InvalidValue { arg, val, err } => format!(
                "error: Invalid value for '{}': {}\n",
                arg, err
            ),
            ClapError::MultipleOccurrence { arg, usage } => format!(
                "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                arg, usage
            ),
            ClapError::InvalidSubcommand { sub, dym, bin, usage } => format!(
                "error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                sub, dym, bin, sub, usage
            ),
            ClapError::UnrecognizedSubcommand { sub, bin } => format!(
                "error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n\t{} help <subcommands>...\n\nFor more information try --help\n",
                sub, bin
            ),
            ClapError::DisplayHelp(h) => h.clone(),
            ClapError::DisplayVersion(v) => v.clone(),
        }
    }
    pub fn is_help(&self) -> bool {
        matches!(self, ClapError::DisplayHelp(_) | ClapError::DisplayVersion(_))
    }
}

pub fn jaro(a: &str, b: &str) -> f64 {
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    let (al, bl) = (ac.len(), bc.len());
    if al == 0 && bl == 0 {
        return 1.0;
    }
    if al == 0 || bl == 0 {
        return 0.0;
    }
    if al == 1 && bl == 1 {
        return if ac[0] == bc[0] { 1.0 } else { 0.0 };
    }
    let search_range = (std::cmp::max(al, bl) / 2) - 1;
    let mut b_consumed = vec![false; bl];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, ae) in ac.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(bl - 1, i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, be) in bc.iter().enumerate() {
            if min_bound <= j && j <= max_bound && ae == be && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / al as f64)
                + (matches / bl as f64)
                + ((matches - transpositions) / matches))
    }
}

pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    let prefix_length = a
        .chars()
        .zip(b.chars())
        .take_while(|&(x, y)| x == y)
        .count();
    let d = j + (0.1 * prefix_length as f64 * (1.0 - j));
    if d <= 1.0 {
        d
    } else {
        1.0
    }
}

pub fn did_you_mean(v: &str, candidates: &[String]) -> Option<String> {
    let mut candidate: Option<(f64, String)> = None;
    for pv in candidates {
        let confidence = jaro_winkler(v, pv);
        if confidence > 0.8 && (candidate.is_none() || candidate.as_ref().unwrap().0 < confidence) {
            candidate = Some((confidence, pv.clone()));
        }
    }
    candidate.map(|(_, c)| c)
}

pub fn sub_candidates(c: &CmdDef) -> Vec<String> {
    let mut v = Vec::new();
    for s in &c.subcommands {
        v.push(s.name.to_string());
        for al in s.aliases {
            v.push(al.to_string());
        }
    }
    v
}

pub fn find_sub<'a>(c: &'a CmdDef, name: &str) -> Option<&'a SubDef> {
    c.subcommands
        .iter()
        .find(|s| s.name == name || s.aliases.iter().any(|a| *a == name))
}

pub struct ParseOutcome {
    pub matches: Matches,
    pub sub: Option<(String, Vec<String>)>,
}

fn usage_str_for(cmd: &CmdDef, prefix: &str, used_names: &[String]) -> String {
    // used: non required, non positional
    let mut used: Vec<&ArgDef> = Vec::new();
    for n in used_names {
        if let Some(a) = find_arg(cmd, n) {
            if !a.required && !a.positional {
                used.push(a);
            }
        }
    }
    if used.is_empty() {
        let mut out = String::new();
        for (i, u) in cmd.usage.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            out.push_str(&u.replace("{bin}", prefix));
        }
        return out;
    }
    let mut parts: Vec<String> = Vec::new();
    for idx in &cmd_required_indices(cmd) {
        let a = &cmd.args[*idx];
        parts.push(arg_usage(a));
    }
    let mut sorted: Vec<&ArgDef> = used.clone();
    sorted.sort_by(|a, b| a.name.cmp(b.name));
    for a in sorted {
        parts.push(arg_usage(a));
    }
    let mut out = String::from(prefix);
    for p in parts {
        out.push(' ');
        out.push_str(&p);
    }
    out
}

fn cmd_required_indices(cmd: &CmdDef) -> Vec<usize> {
    cmd.args
        .iter()
        .enumerate()
        .filter(|(_, a)| a.required)
        .map(|(i, _)| i)
        .collect()
}

pub struct ParsedCmd {
    pub cmd_name: String,
    pub matches: Matches,
}

pub fn parse(
    cmd: &CmdDef,
    argv: &[String],
    prefix: &str,
    is_root: bool,
    bin: &str,
) -> Result<ParseOutcome, ClapError> {
    let mut m = Matches::default();
    let mut pos_counter = 0usize;
    let n_pos = cmd.args.iter().filter(|a| a.positional).count();
    let mut trailing = false;
    let mut i = 0usize;
    while i < argv.len() {
        let arg = argv[i].clone();
        if !trailing && arg == "--" {
            trailing = true;
            i += 1;
            continue;
        }
        let starts_new = !trailing && arg.len() > 1 && arg.starts_with('-');
        if starts_new {
            if arg.starts_with("--") {
                // long arg
                let trimmed = arg.trim_start_matches('-');
                let (name, inline) = match trimmed.find('=') {
                    Some(p) => (trimmed[..p].to_string(), Some(trimmed[p + 1..].to_string())),
                    None => (trimmed.to_string(), None),
                };
                let def = cmd.args.iter().find(|a| !a.positional && a.long == Some(name.as_str()));
                match def {
                    None => {
                        return Err(ClapError::UnknownArg {
                            arg: format!("--{}", name),
                            usage: usage_str_for(cmd, prefix, &m.used),
                        })
                    }
                    Some(a) => {
                        if a.name == "help" {
                            return Err(ClapError::DisplayHelp(render_help(
                                cmd,
                                &HelpCtx { bin: bin.to_string(), env_val: crate::main_env_val() },
                                true,
                            )));
                        }
                        if a.name == "version" {
                            return Err(ClapError::DisplayVersion(version_line(cmd, prefix)));
                        }
                        if a.val_name.is_some() {
                            match inline {
                                Some(v) => m.add_val(a.name, v),
                                None => {
                                    m.add_occ(a.name);
                                    let mut got = false;
                                    while i + 1 < argv.len() {
                                        let nx = &argv[i + 1];
                                        if nx.len() > 1 && nx.starts_with('-') && nx != "--" {
                                            break;
                                        }
                                        m.add_val(a.name, nx.clone());
                                        got = true;
                                        i += 1;
                                        if !a.multiple {
                                            break;
                                        }
                                    }
                                    if !got {
                                        return Err(ClapError::EmptyValue {
                                            arg: arg_usage(a),
                                            usage: usage_str_for(cmd, prefix, &m.used),
                                        });
                                    }
                                }
                            }
                        } else {
                            m.add_occ(a.name);
                        }
                    }
                }
                i += 1;
                continue;
            } else {
                // short cluster
                let chars: Vec<char> = arg.chars().collect();
                let mut j = 1usize;
                let mut consumed_next = false;
                while j < chars.len() {
                    let c = chars[j];
                    let def = cmd
                        .args
                        .iter()
                        .find(|a| !a.positional && a.short == Some(c));
                    match def {
                        None => {
                            return Err(ClapError::UnknownArg {
                                arg: format!("-{}", c),
                                usage: usage_str_for(cmd, prefix, &m.used),
                            })
                        }
                        Some(ad) => {
                            if ad.name == "help" {
                                return Err(ClapError::DisplayHelp(render_help(
                                    cmd,
                                    &HelpCtx { bin: bin.to_string(), env_val: crate::main_env_val() },
                                    false,
                                )));
                            }
                            if ad.name == "version" {
                                return Err(ClapError::DisplayVersion(version_line(cmd, prefix)));
                            }
                            if ad.val_name.is_some() {
                                let rest: String = chars[j + 1..].iter().collect();
                                if !rest.is_empty() {
                                    let v = rest.strip_prefix('=').unwrap_or(&rest).to_string();
                                    m.add_val(ad.name, v);
                                    j = chars.len();
                                    break;
                                } else {
                                    m.add_occ(ad.name);
                                    let mut got = false;
                                    while i + 1 < argv.len() {
                                        let nx = &argv[i + 1];
                                        if nx.len() > 1 && nx.starts_with('-') && nx != "--" {
                                            break;
                                        }
                                        m.add_val(ad.name, nx.clone());
                                        got = true;
                                        i += 1;
                                        consumed_next = true;
                                        if !ad.multiple {
                                            break;
                                        }
                                    }
                                    if !got {
                                        return Err(ClapError::EmptyValue {
                                            arg: arg_usage(ad),
                                            usage: usage_str_for(cmd, prefix, &m.used),
                                        });
                                    }
                                    j = chars.len();
                                    break;
                                }
                            } else {
                                m.add_occ(ad.name);
                                j += 1;
                            }
                        }
                    }
                }
                if !consumed_next {
                    i += 1;
                }
                continue;
            }
        }
        // sub command?
        if is_root && !trailing {
            if let Some(sc) = find_sub(cmd, &arg) {
                return Ok(ParseOutcome {
                    matches: m,
                    sub: Some((sc.name.to_string(), argv[i + 1..].to_vec())),
                });
            }
        }
        if is_root {
            if let Some(c) = did_you_mean(&arg, &sub_candidates(cmd)) {
                return Err(ClapError::InvalidSubcommand {
                    sub: arg.clone(),
                    dym: c,
                    bin: bin.to_string(),
                    usage: usage_str_for(cmd, prefix, &m.used),
                });
            }
        }
        if pos_counter < n_pos {
            let p = &cmd.args[pos_counter_of(cmd, pos_counter)];
            m.add_val(p.name, arg.clone());
            if p.last {
                trailing = true;
            }
            if !p.multiple {
                pos_counter += 1;
            }
        } else {
            return Err(ClapError::UnknownArg {
                arg: arg.clone(),
                usage: usage_str_for(cmd, prefix, &m.used),
            });
        }
        i += 1;
    }
    Ok(ParseOutcome { matches: m, sub: None })
}

fn pos_counter_of(cmd: &CmdDef, idx: usize) -> usize {
    let mut seen = 0usize;
    for (i, a) in cmd.args.iter().enumerate() {
        if a.positional {
            if seen == idx {
                return i;
            }
            seen += 1;
        }
    }
    cmd.args.len()
}

pub fn version_line(cmd: &CmdDef, prefix: &str) -> String {
    if cmd.name == "pier" {
        format!("pier {}", cmd.version)
    } else {
        format!("{}-{} {}", prefix, cmd.name, cmd.version)
    }
}

/// post-parse validation
pub fn validate(cmd: &CmdDef, m: &mut Matches, prefix: &str) -> Result<(), ClapError> {
    // missing required
    let mut missing: Vec<String> = Vec::new();
    for a in &cmd.args {
        if a.required {
            if a.positional {
                if m.vals.get(a.name).map(|v| v.is_empty()).unwrap_or(true) {
                    missing.push(arg_usage(a));
                }
            } else if !m.is_present(a.name) {
                missing.push(arg_usage(a));
            }
        }
    }
    if !missing.is_empty() {
        return Err(ClapError::MissingRequired {
            args: missing,
            usage: usage_str_for(cmd, prefix, &m.used),
        });
    }
    // occurrences
    for a in &cmd.args {
        if !a.positional && !a.multiple {
            if m.occurrences_of(a.name) > 1 {
                return Err(ClapError::MultipleOccurrence {
                    arg: arg_usage(a),
                    usage: usage_str_for(cmd, prefix, &m.used),
                });
            }
        }
    }
    Ok(())
}
