use crate::cli::*;
use std::collections::HashMap;

#[derive(Default)]
pub struct Matches {
    pub vals: HashMap<String, Vec<String>>,
    pub occ: HashMap<String, usize>,
    pub used: Vec<String>, // names of non-positional args, insertion order
}

impl Matches {
    fn add_val(&mut self, name: &str, v: String) {
        self.vals.entry(name.to_string()).or_default().push(v);
        if !self.used.contains(&name.to_string()) {
            self.used.push(name.to_string());
        }
    }
    fn add_occ(&mut self, name: &str) {
        *self.occ.entry(name.to_string()).or_insert(0) += 1;
        if !self.used.contains(&name.to_string()) {
            self.used.push(name.to_string());
        }
    }
    pub fn value_of(&self, name: &str) -> Option<&str> {
        self.vals.get(name).and_then(|v| v.first()).map(|s| s.as_str())
    }
    pub fn values_of(&self, name: &str) -> Vec<String> {
        self.vals.get(name).cloned().unwrap_or_default()
    }
    pub fn is_present(&self, name: &str) -> bool {
        self.occ.contains_key(name)
    }
    pub fn occurrences_of(&self, name: &str) -> usize {
        *self.occ.get(name).unwrap_or(&0)
    }
}

pub enum ClapError {
