fn pos_counter_of(cmd: &CmdDef, idx: usize) -> usize {
    let mut seen = 0usize;
    for (i, a) in cmd.args.iter().enumerate() {
        if a.positional {
            if seen == idx {
                return i;
            }
            seen += 1;
        }
    }
    cmd.args.len()
}

pub fn version_line(cmd: &CmdDef, prefix: &str) -> String {
    if cmd.name == "pier" {
        format!("pier {}", cmd.version)
    } else {
        format!("{}-{} {}", prefix, cmd.name, cmd.version)
    }
}

/// post-parse validation
pub fn validate(cmd: &CmdDef, m: &mut Matches, prefix: &str) -> Result<(), ClapError> {
    // missing required
    let mut missing: Vec<String> = Vec::new();
    for a in &cmd.args {
        if a.required {
            if a.positional {
                if m.vals.get(a.name).map(|v| v.is_empty()).unwrap_or(true) {
