    for a in &cmd.args {
        if !a.positional && !a.multiple {
            if m.occurrences_of(a.name) > 1 {
                return Err(ClapError::MultipleOccurrence {
                    arg: arg_usage(a),
                    usage: usage_str_for(cmd, prefix, &m.used),
                });
            }
        }
    }
    Ok(())
}
