fn usage_str_for(cmd: &CmdDef, prefix: &str, used_names: &[String]) -> String {
    // used: non required, non positional
    let mut used: Vec<&ArgDef> = Vec::new();
    for n in used_names {
        if let Some(a) = find_arg(cmd, n) {
            if !a.required && !a.positional {
                used.push(a);
            }
        }
    }
    if used.is_empty() {
        let mut out = String::new();
        for (i, u) in cmd.usage.iter().enumerate() {
