use clap::{ClapError, Matches};
use config::{Config, Script};
use std::path::{Path, PathBuf};

pub fn main_env_val() -> String {
    std::env::var("PIER_CONFIG_PATH").unwrap_or_default()
}

const NO_SCRIPTS: &str = "No scripts exist. Would you like to add a new script?";

fn bin_name() -> String {
    match std::env::args_os().next() {
        Some(a) => {
            let p = Path::new(&a);
            match p.file_name() {
                Some(f) => f.to_string_lossy().to_string(),
                None => a.to_string_lossy().to_string(),
            }
        }
        None => "pier".to_string(),
    }
}

fn main() {
    let code = run();
    std::process::exit(code);
}

fn fail(msg: &str) -> i32 {
    eprintln!("error: {}", msg);
    1
}

fn handle_clap(e: ClapError) -> i32 {
    match e {
        ClapError::DisplayHelp(h) => {
            print!("{}", h);
            0
        }
        ClapError::DisplayVersion(v) => {
            println!("{}", v);
            0
        }
        other => {
            eprint!("{}", other.render());
            1
        }
    }
}

fn ctx(bin: &str) -> cli::HelpCtx {
    cli::HelpCtx { bin: bin.to_string(), prefix: bin.to_string(), env_val: main_env_val() }
}

fn run() -> i32 {
    let bin = bin_name();
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let root = cli::build_root();
    let outcome = match clap::parse(&root, &argv, &bin, true, &bin) {
        Ok(o) => o,
        Err(e) => return handle_clap(e),
    };
    let mut m = outcome.matches;
    let verbose = m.is_present("verbose");
    let explicit = m.value_of("config-file").map(PathBuf::from);
    let (sub, sub_args) = match outcome.sub {
        Some(s) => s,
        None => {
            if let Err(e) = clap::validate(&root, &mut m, &bin) {
                return handle_clap(e);
            }
            return run_alias(&m, explicit.as_ref(), verbose);
        }
    };
    let mut cmd = if sub == "help" {
        cli::build_help_sub()
    } else {
        match cli::build_sub(&sub) {
            Some(c) => c,
            None => return fail("unknown subcommand"),
        }
    };
    let prefix = format!("{} {}", bin, sub);
    cmd.name = if sub == "help" { "help" } else { sub.as_str() };
    let out = match clap::parse(&cmd, &sub_args, &prefix, false, &bin) {
        Ok(o) => o,
        Err(e) => return handle_clap(e),
    };
    let mut sm = out.matches;
    if let Err(e) = clap::validate(&cmd, &mut sm, &prefix) {
        return handle_clap(e);
    }
    match sub.as_str() {
        "add" => cmd_add(&sm, explicit.as_ref()),
        "config-init" => cmd_config_init(&sm, explicit.as_ref()),
        "copy" => cmd_copy(&sm, explicit.as_ref()),
        "edit" => cmd_edit(&sm, explicit.as_ref()),
        "list" => cmd_list(&sm, explicit.as_ref()),
        "move" => cmd_move(&sm, explicit.as_ref()),
        "remove" => cmd_remove(&sm, explicit.as_ref()),
        "run" => cmd_run(&sm, explicit.as_ref(), verbose),
        "show" => cmd_show(&sm, explicit.as_ref()),
        "help" => cmd_help(&sm, &bin),
        _ => fail("unknown subcommand"),
    }
}

fn resolve(explicit: Option<&PathBuf>) -> Result<PathBuf, String> {
    match config::resolve(explicit) {
        config::Resolved::Path(p) => Ok(p),
        config::Resolved::NotFound => {
            Err("No default config file found. See help for more info.".to_string())
        }
    }
}

fn load(explicit: Option<&PathBuf>) -> Result<(PathBuf, Config), i32> {
    let path = match resolve(explicit) {
        Ok(p) => p,
        Err(e) => return Err(fail(&e)),
    };
    match config::read_config(&path) {
        Ok(c) => Ok((path, c)),
        Err(e) => Err(fail(&e)),
    }
}

fn save(path: &Path, cfg: &Config) -> Result<(), i32> {
    match config::write_config(path, cfg) {
        Ok(()) => Ok(()),
        Err(e) => Err(fail(&e)),
    }
}

// ---------------------------------------------------------------------------

fn run_alias(m: &Matches, explicit: Option<&PathBuf>, verbose: bool) -> i32 {
    let (_, cfg) = match load(explicit) {
        Ok(x) => x,
        Err(c) => return c,
    };
    if cfg.scripts.is_empty() {
        return fail(NO_SCRIPTS);
    }
    let alias = m.value_of("alias").unwrap().to_string();
    let args = m.values_of("args");
    execute(&cfg, &alias, &args, verbose)
}

fn cmd_run(m: &Matches, explicit: Option<&PathBuf>, verbose: bool) -> i32 {
    let (_, cfg) = match load(explicit) {
        Ok(x) => x,
        Err(c) => return c,
    };
    if cfg.scripts.is_empty() {
        return fail(NO_SCRIPTS);
    }
    let alias = m.value_of("alias").unwrap().to_string();
    let args = m.values_of("args");
    execute(&cfg, &alias, &args, verbose)
}

fn execute(cfg: &Config, alias: &str, args: &[String], verbose: bool) -> i32 {
    let script = match cfg.scripts.get(alias) {
        Some(s) => s,
        None => {
            return fail(&format!(
                "AliasNotFound: No script found by alias {}",
                alias
            ))
        }
    };
    if verbose {
        println!("Starting script \"{}\"", alias);
        println!("{}", "-".repeat(25));
    }
    let mut cmd = std::process::Command::new("/bin/sh");
    cmd.arg("-c").arg(&script.command).arg(alias);
    for a in args {
        cmd.arg(a);
    }
    let status = match cmd.status() {
        Ok(s) => s,
        Err(e) => {
            if verbose {
                println!("{}", "-".repeat(25));
                println!("Script complete");
            }
            return fail(&format!("ShellError: Failed when trying to run the script {}", e));
        }
    };
    if verbose {
        println!("{}", "-".repeat(25));
        println!("Script complete");
    }
    status.code().unwrap_or(0)
}

fn cmd_show(m: &Matches, explicit: Option<&PathBuf>) -> i32 {
    let (_, cfg) = match load(explicit) {
        Ok(x) => x,
        Err(c) => return c,
    };
    if cfg.scripts.is_empty() {
        return fail(NO_SCRIPTS);
    }
    let alias = m.value_of("alias").unwrap();
    match cfg.scripts.get(alias) {
        Some(s) => {
            println!("{}", s.command);
            0
        }
        None => fail(&format!("AliasNotFound: No script found by alias {}", alias)),
    }
}

fn cmd_remove(m: &Matches, explicit: Option<&PathBuf>) -> i32 {
    let (path, mut cfg) = match load(explicit) {
        Ok(x) => x,
        Err(c) => return c,
    };
    if cfg.scripts.is_empty() {
        return fail(NO_SCRIPTS);
    }
    let alias = m.value_of("alias").unwrap();
    if !cfg.scripts.contains_key(alias) {
        return fail(&format!("AliasNotFound: No script found by alias {}", alias));
    }
    cfg.scripts.remove(alias);
    println!("Removed {}", alias);
    match save(&path, &cfg) {
        Ok(()) => 0,
        Err(c) => c,
    }
}

fn cmd_copy(m: &Matches, explicit: Option<&PathBuf>) -> i32 {
    let (path, mut cfg) = match load(explicit) {
        Ok(x) => x,
        Err(c) => return c,
    };
    let from = m.value_of("from-alias").unwrap();
    let to = m.value_of("to-alias").unwrap();
    if cfg.scripts.contains_key(to) {
        return fail(&format!("AliasAlreadyExists:  {}", to));
    }
    let script = match cfg.scripts.get(from) {
        Some(s) => s.clone(),
        None => {
            return fail(&format!(
                "AliasNotFound: No script found by alias {}",
                from
            ))
        }
    };
    cfg.scripts.insert(to.to_string(), script);
    println!("Copy from alias {} to new alias {}", from, to);
    match save(&path, &cfg) {
        Ok(()) => 0,
        Err(c) => c,
    }
}

fn cmd_move(m: &Matches, explicit: Option<&PathBuf>) -> i32 {
    let (path, mut cfg) = match load(explicit) {
        Ok(x) => x,
        Err(c) => return c,
    };
    let from = m.value_of("from-alias").unwrap();
    let to = m.value_of("to-alias").unwrap();
    if cfg.scripts.contains_key(to) && !m.is_present("force") {
        return fail(&format!("AliasAlreadyExists:  {}", to));
    }
    let script = match cfg.scripts.remove(from) {
        Some(s) => s,
        None => {
            return fail(&format!(
                "AliasNotFound: No script found by alias {}",
                from
            ))
        }
    };
    cfg.scripts.insert(to.to_string(), script);
    println!("Move from alias {} to new alias {}", from, to);
    match save(&path, &cfg) {
        Ok(()) => 0,
        Err(c) => c,
    }
}

fn cmd_list(m: &Matches, explicit: Option<&PathBuf>) -> i32 {
    let (_, cfg) = match load(explicit) {
        Ok(x) => x,
        Err(c) => return c,
    };
    if cfg.scripts.is_empty() {
        return fail(NO_SCRIPTS);
    }
    let tags = m.values_of("tag");
    let list_aliases = m.is_present("list_aliases");
    let cmd_full = m.is_present("cmd_full");
    let mut width: Option<usize> = m.value_of("cmd_width").and_then(|s| s.parse().ok());
    if width.is_none() {
        width = cfg.default.command_width;
    }
    let default_width = 80usize;

    let mut selected: Vec<(String, &Script)> = Vec::new();
    for (alias, script) in &cfg.scripts {
        if tags.is_empty() {
            selected.push((alias.clone(), script));
        } else {
            for t in &tags {
                let has = script.tags.as_ref().map(|ts| ts.contains(t)).unwrap_or(false);
                if has {
                    selected.push((alias.clone(), script));
                }
            }
        }
    }

    if list_aliases {
        for (alias, _) in &selected {
            println!("{}", alias);
        }
        return 0;
    }

    let cmd_w = if cmd_full {
        usize::MAX
    } else {
        width.unwrap_or(default_width)
    };
    let mut rows: Vec<Vec<String>> = Vec::new();
    for (alias, script) in &selected {
        let cmd_disp = if cmd_full {
            script.command.clone()
        } else {
            first_line(&script.command)
                .chars()
                .take(cmd_w)
                .collect::<String>()
        };
        let tags_disp = script
            .tags
            .as_ref()
            .map(|t| t.join(","))
            .unwrap_or_default();
        let desc = script.description.clone().unwrap_or_default();
        rows.push(vec![alias.clone(), tags_disp, cmd_disp, desc]);
    }
    let t = table::Table {
        headers: vec![
            "Alias".to_string(),
            "Tags".to_string(),
            "Command".to_string(),
            "Description".to_string(),
        ],
        rows,
    };
    print!("{}", t.render());
    0
}

fn first_line(s: &str) -> &str {
    match s.find('\n') {
        Some(i) => &s[..i],
        None => s,
    }
}

fn cmd_config_init(m: &Matches, explicit: Option<&PathBuf>) -> i32 {
    let _ = m;
    let explicit_path = explicit.cloned().or_else(|| {
        std::env::var_os("PIER_CONFIG_PATH").map(PathBuf::from)
    });
    let path = match explicit_path {
        Some(p) => p,
        None => config::default_init_path(),
    };
    if path.exists() {
        return fail(&format!(
            "Cannot initialize config at {}, file already exists.",
            path.display()
        ));
    }
    let dir: PathBuf = match &explicit_path {
        Some(p) => match p.parent() {
            Some(d) => d.to_path_buf(),
            None => return Err(0).unwrap_or(()), // unreachable
        },
        None => config::config_dir()
            .map(|d| d.join("pier"))
            .unwrap_or_default(),
    };
    if let Some(p) = &explicit_path {
        if p.parent().is_none() {
            // nothing to create
        } else if !dir.exists() {
            if let Err(e) = std::fs::create_dir(&dir) {
                return fail(&format!("Failed to create directory. {}", e));
            }
        }
    } else if !dir.exists() {
        if let Err(e) = std::fs::create_dir(&dir) {
            return fail(&format!("Failed to create directory. {}", e));
        }
    }
    let cfg = config::default_config();
    println!("Added hello-pier");
    match config::write_config(&path, &cfg) {
        Ok(()) => 0,
        Err(e) => fail(&e),
    }
}

fn cmd_add(m: &Matches, explicit: Option<&PathBuf>) -> i32 {
    let (path, mut cfg) = match load(explicit) {
        Ok(x) => x,
        Err(c) => return c,
    };
    let alias = m.value_of("alias").unwrap().to_string();
    let description = m.value_of("description").map(|s| s.to_string());
    let tags = {
        let t = m.values_of("tag");
        if t.is_empty() {
            None
        } else {
            Some(t)
        }
    };
    let command: String = match m.value_of("command") {
        Some(c) => c.to_string(),
        None => match editor_input("") {
            Ok(c) => c,
            Err(e) => return fail(&e),
        },
    };
    if cfg.scripts.contains_key(&alias) && !m.is_present("force") {
        return fail(&format!("AliasAlreadyExists:  {}", alias));
    }
    cfg.scripts.insert(
        alias.clone(),
        Script { command, description, tags },
    );
    println!("Added {}", alias);
    match save(&path, &cfg) {
        Ok(()) => 0,
        Err(c) => c,
    }
}

fn cmd_edit(m: &Matches, explicit: Option<&PathBuf>) -> i32 {
    let (path, mut cfg) = match load(explicit) {
        Ok(x) => x,
        Err(c) => return c,
    };
    if cfg.scripts.is_empty() {
        return fail(NO_SCRIPTS);
    }
    let alias = m.value_of("alias").unwrap().to_string();
    let current = match cfg.scripts.get(&alias) {
        Some(s) => s.command.clone(),
        None => {
            return fail(&format!(
                "AliasNotFound: No script found by alias {}",
                alias
            ))
        }
    };
    let new = match editor_input(&current) {
        Ok(c) => c,
        Err(e) => return fail(&e),
    };
    cfg.scripts.get_mut(&alias).unwrap().command = new;
    println!("Edited {}", alias);
    match save(&path, &cfg) {
        Ok(()) => 0,
        Err(c) => c,
    }
}

fn editor_input(initial: &str) -> Result<String, String> {
    let editor = std::env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());
    let tmp = std::env::temp_dir().join(format!(
        "xvrqt_scrawl_{}_0",
