{"command": "cd /workspace && cat > /tmp/gen_toml.py <<'PYEOF'
src = r'''
// Minimal TOML value model + parser/serializer reproducing the `toml` crate
// (0.5.x) messages and formatting used by the original program.

#[derive(Debug, Clone)]
pub enum Value {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Datetime, // deserialized as a "map" by the original
    Array(Vec<Value>),
    Table(Vec<(String, Value)>),
}

impl Value {
    pub fn get(&self, k: &str) -> Option<&Value> {
        match self {
            Value::Table(v) => v.iter().find(|(key, _)| key == k).map(|(_, x)| x),
            _ => None,
        }
    }
    pub fn type_desc(&self) -> String {
        match self {
            Value::Str(s) => format!("string {:?}", s),
            Value::Int(i) => format!("integer `{}`", i),
            Value::Float(f) => format!("floating point `{}`", fmt_float(*f)),
            Value::Bool(b) => format!("boolean `{}`", b),
            Value::Datetime => "map".to_string(),
            Value::Array(_) => "sequence".to_string(),
            Value::Table(_) => "map".to_string(),
        }
    }
    pub fn is_table(&self) -> bool {
        matches!(*self, Value::Table(_))
    }
    pub fn unexpected(&self) -> String {
        self.type_desc()
    }
}

pub fn fmt_float(f: f64) -> String {
    if f.is_nan() {
        "NaN".to_string()
    } else if f.is_infinite() {
        if f > 0.0 { "inf".to_string() } else { "-inf".to_string() }
    } else {
        format!("{}", f)
    }
}

/// rust's `char::escape_default`
fn escape_default(c: char) -> String {
    match c {
        '\t' => "\\t".to_string(),
        '\r' => "\\r".to_string(),
        '\n' => "\\n".to_string(),
        '\\' => "\\\\".to_string(),
        '\'' => "\\'".to_string(),
        '"' => "\\\"".to_string(),
        c if ('\u{20}'..='\u{7e}').contains(&c) => c.to_string(),
        c => format!("\\u{{{:x}}}", c as u32),
    }
}

#[derive(Debug, Clone)]
pub enum TokErr {
    UnexpectedEof,
    InvalidCharInString(char),
    InvalidEscape(char),
    InvalidHexEscape(char),
    InvalidEscapeValue(u32),
    NewlineInString,
    Unexpected(char),
    UnterminatedString,
    NewlineInTableKey,
    MultilineStringKey,
    Wanted { expected: &'static str, found: &'static str },
    NumberInvalid,
    DateInvalid,
    DuplicateTable(String),
    RedefineAsArray,
    EmptyTableKey,
    MixedTableArray,
    MixedTypes,
}

impl TokErr {
    pub fn message(&self) -> String {
        match self {
            TokErr::UnexpectedEof => "unexpected eof encountered".to_string(),
            TokErr::InvalidCharInString(c) => {
                format!("invalid character in string: `{}`", escape_default(*c))
            }
            TokErr::InvalidEscape(c) => format!(
                "invalid escape character in string: `{}`",
                escape_default(*c)
            ),
            TokErr::InvalidHexEscape(c) => format!(
                "invalid hex escape character in string: `{}`",
                escape_default(*c)
            ),
            TokErr::InvalidEscapeValue(v) => format!("invalid escape value: `{}`", v),
            TokErr::NewlineInString => "newline in string found".to_string(),
            TokErr::Unexpected(c) => {
                format!("unexpected character found: `{}`", escape_default(*c))
            }
            TokErr::UnterminatedString => "unterminated string".to_string(),
            TokErr::NewlineInTableKey => "newline in table key found".to_string(),
            TokErr::MultilineStringKey => "multiline strings are not allowed for key".to_string(),
            TokErr::Wanted { expected, found } => {
                format!("expected {}, found {}", expected, found)
            }
            TokErr::NumberInvalid => "invalid number".to_string(),
            TokErr::DateInvalid => "invalid date".to_string(),
            TokErr::DuplicateTable(s) => format!("redefinition of table `{}`", s),
            TokErr::RedefineAsArray => "table redefined as array".to_string(),
            TokErr::EmptyTableKey => "empty table key found".to_string(),
            TokErr::MixedTableArray => "key redefined as table/array".to_string(),
            TokErr::MixedTypes => "mixed types in an array".to_string(),
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Whitespace,
    Newline,
    Comment,
    Equals,
    Period,
    Comma,
    Colon,
    PlusSign,
    LeftBrace,
    RightBrace,
    LeftBracket,
    RightBracket,
    Keylike(String),
    Str { val: String, multiline: bool },
}

impl Token {
    fn describe(&self) -> &'static str {
        match self {
            Token::Whitespace => "whitespace",
            Token::Newline => "a newline",
            Token::Comment => "a comment",
            Token::Equals => "an equals",
            Token::Period => "a period",
            Token::Comma => "a comma",
            Token::Colon => "a colon",
            Token::PlusSign => "a plus sign",
            Token::LeftBrace => "a left brace",
            Token::RightBrace => "a right brace",
            Token::LeftBracket => "a left bracket",
            Token::RightBracket => "a right bracket",
            Token::Keylike(_) => "an identifier",
            Token::Str { .. } => "a string",
        }
    }
}

pub struct Tokenizer<'a> {
    src: &'a [u8],
    pos: usize,
}

fn is_keylike(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'-' || b == b'_'
}

impl<'a> Tokenizer<'a> {
    pub fn new(src: &'a [u8]) -> Tokenizer<'a> {
        Tokenizer { src, pos: 0 }
    }
    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }
    fn peek_at(&self, n: usize) -> Option<u8> {
        self.src.get(self.pos + n).copied()
    }
    pub fn line_of(&self, at: usize) -> usize {
        let mut l = 1;
        for i in 0..at.min(self.src.len()) {
            if self.src[i] == b'\n' {
                l += 1;
            }
        }
        l
    }
    fn err_at(&self, at: usize, e: TokErr) -> ParseError {
        ParseError { msg: e.message(), line: Some(self.line_of(at)), key: None }
    }
    fn eof_err(&self, at: usize) -> ParseError {
        ParseError {
            msg: TokErr::UnexpectedEof.message(),
            line: Some(self.line_of(self.src.len())),
            key: None,
        }
    }

    pub fn next_token(&mut self) -> Result<Option<(Token, usize, usize)>, ParseError> {
        let start = self.pos;
        let c = match self.peek() {
            None => return Ok(None),
            Some(c) => c,
        };
        let tok = match c {
            b'\n' => {
                self.pos += 1;
                Token::Newline
            }
            b'\r' => {
                if self.peek_at(1) == Some(b'\n') {
                    self.pos += 2;
                    Token::Newline
                } else {
                    return Err(self.err_at(start, TokErr::Unexpected('\r')));
                }
            }
            b' ' | b'\t' => {
                while let Some(c) = self.peek() {
                    if c == b' ' || c == b'\t' {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                Token::Whitespace
            }
            b'#' => {
                while let Some(c) = self.peek() {
                    if c == b'\n' {
                        break;
                    }
                    self.pos += 1;
                }
                Token::Comment
            }
            b'=' => {
                self.pos += 1;
                Token::Equals
            }
            b'.' => {
                self.pos += 1;
                Token::Period
            }
            b',' => {
                self.pos += 1;
                Token::Comma
            }
            b':' => {
                self.pos += 1;
                Token::Colon
            }
            b'+' => {
                self.pos += 1;
                Token::PlusSign
            }
            b'{' => {
                self.pos += 1;
                Token::LeftBrace
            }
            b'}' => {
                self.pos += 1;
                Token::RightBrace
            }
            b'[' => {
                self.pos += 1;
                Token::LeftBracket
            }
            b']' => {
                self.pos += 1;
                Token::RightBracket
            }
            b'\'' => self.literal_string(start)?,
            b'"' => self.basic_string(start)?,
            _ if is_keylike(c) => {
                while let Some(c) = self.peek() {
                    if is_keylike(c) {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                Token::Keylike(String::from_utf8_lossy(&self.src[start..self.pos]).to_string())
            }
            _ => {
                return Err(self.err_at(start, TokErr::Unexpected(c as char)));
            }
        };
        Ok(Some((tok, start, self.pos)))
    }

    fn literal_string(&mut self, start: usize) -> Result<Token, ParseError> {
        let multi = self.peek_at(1) == Some(b'\'') && self.peek_at(2) == Some(b'\'');
        if multi {
            self.pos += 3;
            if self.peek() == Some(b'\r') && self.peek_at(1) == Some(b'\n') {
                self.pos += 2;
            } else if self.peek() == Some(b'\n') {
                self.pos += 1;
            }
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err(self.pos)),
                    Some(b'\'') => {
                        if self.peek_at(1) == Some(b'\'') && self.peek_at(2) == Some(b'\'') {
                            self.pos += 3;
                            break;
                        } else {
                            out.push(b'\'');
                            self.pos += 1;
                        }
                    }
                    Some(c) => {
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            match String::from_utf8(out) {
                Ok(s) => Ok(Token::Str { val: s, multiline: true }),
                Err(_) => Err(self.err_at(start, TokErr::UnterminatedString)),
            }
        } else {
            self.pos += 1;
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err(self.pos)),
                    Some(b'\n') => {
                        return Err(self.err_at(self.pos, TokErr::NewlineInString))
                    }
                    Some(b'\'') => {
                        self.pos += 1;
                        break;
                    }
                    Some(c) => {
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            match String::from_utf8(out) {
                Ok(s) => Ok(Token::Str { val: s, multiline: false }),
                Err(_) => Err(self.err_at(start, TokErr::UnterminatedString)),
            }
        }
    }

    fn basic_string(&mut self, start: usize) -> Result<Token, ParseError> {
        let multi = self.peek_at(1) == Some(b'"') && self.peek_at(2) == Some(b'"');
        if multi {
            self.pos += 3;
            if self.peek() == Some(b'\r') && self.peek_at(1) == Some(b'\n') {
                self.pos += 2;
            } else if self.peek() == Some(b'\n') {
                self.pos += 1;
            }
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err(self.pos)),
                    Some(b'"') => {
                        if self.peek_at(1) == Some(b'"') && self.peek_at(2) == Some(b'"') {
                            self.pos += 3;
                            break;
                        } else {
                            out.push(b'"');
                            self.pos += 1;
                        }
                    }
                    Some(b'\\') => {
                        self.pos += 1;
                        self.escape(&mut out)?;
                    }
                    Some(c) => {
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            match String::from_utf8(out) {
                Ok(s) => Ok(Token::Str { val: s, multiline: true }),
                Err(_) => Err(self.err_at(start, TokErr::UnterminatedString)),
            }
        } else {
            self.pos += 1;
            let mut out: Vec<u8> = Vec::new();
            loop {
                match self.peek() {
                    None => return Err(self.eof_err(self.pos)),
                    Some(b'\n') => {
                        return Err(self.err_at(self.pos, TokErr::NewlineInString))
                    }
                    Some(b'"') => {
                        self.pos += 1;
                        break;
                    }
                    Some(b'\\') => {
                        self.pos += 1;
                        self.escape(&mut out)?;
                    }
                    Some(c) => {
                        out.push(c);
                        self.pos += 1;
                    }
                }
            }
            match String::from_utf8(out) {
                Ok(s) => Ok(Token::Str { val: s, multiline: false }),
                Err(_) => Err(self.err_at(start, TokErr::UnterminatedString)),
            }
        }
    }

    fn escape(&mut self, out: &mut Vec<u8>) -> Result<(), ParseError> {
        let at = self.pos;
        let c = match self.peek() {
            None => return Err(self.eof_err(self.pos)),
            Some(c) => c,
        };
        self.pos += 1;
        match c {
            b'b' => out.push(8),
            b't' => out.push(b'\t'),
            b'n' => out.push(b'\n'),
            b'f' => out.push(12),
            b'r' => out.push(b'\r'),
            b'"' => out.push(b'"'),
            b'\\' => out.push(b'\\'),
            b'u' | b'U' => {
                let n = if c == b'u' { 4 } else { 8 };
                let mut v: u32 = 0;
                for _ in 0..n {
                    let d = match self.peek() {
                        None => return Err(self.eof_err(self.pos)),
                        Some(d) => d,
                    };
                    match (d as char).to_digit(16) {
                        None => {
                            self.pos += 1;
                            return Err(self.err_at(at, TokErr::InvalidHexEscape(d as char)));
                        }
                        Some(h) => {
                            v = v * 16 + h;
                            self.pos += 1;
                        }
                    }
                }
                match std::char::from_u32(v) {
                    None => return Err(self.err_at(at, TokErr::InvalidEscapeValue(v))),
                    Some(ch) => {
                        let mut buf = [0u8; 4];
                        out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                    }
                }
            }
            _ => return Err(self.err_at(at, TokErr::InvalidEscape(c as char))),
        }
        Ok(())
    }
}

#[derive(Debug, Clone)]
pub struct ParseError {
    pub msg: String,
    pub line: Option<usize>,
    pub key: Option<String>,
}

impl ParseError {
    pub fn to_display(&self) -> String {
        let mut s = self.msg.clone();
        if let Some(k) = &self.key {
            s.push_str(&format!(" for key `{}`", k));
        }
        if let Some(l) = self.line {
            s.push_str(&format!(" at line {}", l));
        }
        s
    }
}

struct Parser<'a> {
    t: Tokenizer<'a>,
    peeked: Option<Option<(Token, usize, usize)>>,
}

impl<'a> Parser<'a> {
    fn new(src: &'a [u8]) -> Parser<'a> {
        Parser { t: Tokenizer::new(src), peeked: None }
    }
    fn peek(&mut self) -> Result<Option<(Token, usize, usize)>, ParseError> {
        if self.peeked.is_none() {
            let n = self.t.next_token()?;
            self.peeked = Some(n);
        }
        Ok(self.peeked.as_ref().unwrap().clone())
    }
    fn next(&mut self) -> Result<Option<(Token, usize, usize)>, ParseError> {
        if let Some(p) = self.peeked.take() {
            return Ok(p);
        }
        self.t.next_token()
    }
    fn eof_line(&self) -> usize {
        self.t.line_of(self.t.src.len())
    }
}

fn token_name(tok: &Token) -> &'static str {
    tok.describe()
}

pub fn parse(src: &str) -> Result<Value, ParseError> {
    let bytes = src.as_bytes();
    let mut p = Parser::new(bytes);
    let mut root: Vec<(String, Value)> = Vec::new();
    let mut cur: Vec<String> = Vec::new();
    let mut tables: Vec<Vec<String>> = Vec::new();
    let mut aots: Vec<Vec<String>> = Vec::new();

    loop {
        skip_ws_comments_newlines(&mut p)?;
        let (tok, at, end) = match p.peek()? {
            None => break,
            Some(x) => x,
        };
        match tok {
            Token::LeftBracket => {
                p.next()?;
                let array = if let Some((Token::LeftBracket, _, _)) = p.peek()? {
                    p.next()?;
                    true
                } else {
                    false
                };
                let keys = parse_key_path(&mut p)?;
                skip_inline_ws(&mut p)?;
                match p.peek()? {
                    Some((Token::RightBracket, _, _)) => {
                        p.next()?;
                    }
                    Some((t, a, _)) => {
                        return Err(want_err(&p, a, "a right bracket", token_name(&t)))
                    }
                    None => return Err(eof_err(&p)),
                }
                if array {
                    match p.peek()? {
                        Some((Token::LeftBracket, _, _)) => {
                            p.next()?;
                        }
                        Some((t, a, _)) => {
                            return Err(want_err(&p, a, "a right bracket", token_name(&t)))
                        }
                        None => return Err(eof_err(&p)),
                    }
                }
                skip_inline_ws(&mut p)?;
                match p.peek()? {
                    None => {}
                    Some((Token::Comment, _, _)) | Some((Token::Newline, _, _)) => {}
                    Some((t, a, _)) => {
                        return Err(want_err(&p, a, "newline", token_name(&t)))
                    }
                }
                if array {
                    if tables.contains(&keys) || aots.contains(&keys) {
                        return Err(ParseError {
                            msg: TokErr::DuplicateTable(keys.join(".")).message(),
                            line: Some(p.t.line_of(at)),
                            key: Some(keys.join(".")),
                        });
                    }
                    aots.push(keys.clone());
                } else {
                    if tables.contains(&keys) || aots.contains(&keys) {
                        return Err(ParseError {
                            msg: TokErr::DuplicateTable(keys.join(".")).message(),
                            line: Some(p.t.line_of(at)),
                            key: Some(keys.join(".")),
                        });
                    }
                    tables.push(keys.clone());
                }
                cur = keys;
            }
            Token::Keylike(_) | Token::Str { .. } => {
                let keys = parse_key_path(&mut p)?;
                skip_inline_ws(&mut p)?;
                match p.peek()? {
                    Some((Token::Equals, _, _)) => {
                        p.next()?;
                    }
                    Some((t, a, _)) => {
                        return Err(want_err(&p, a, "an equals", token_name(&t)))
                    }
                    None => return Err(eof_err(&p)),
                }
                skip_inline_ws(&mut p)?;
                let val = parse_value(&mut p)?;
                let mut path = cur.clone();
                path.extend(keys.iter().cloned());
                insert_value(&mut root, &path, val);
                skip_inline_ws(&mut p)?;
                match p.peek()? {
                    None => {}
                    Some((Token::Comment, _, _)) | Some((Token::Newline, _, _)) => {
                        p.next()?;
                    }
                    Some((t, a, _)) => {
                        return Err(want_err(&p, a, "newline", token_name(&t)))
                    }
                }
                let _ = end;
            }
            _ => {
                return Err(want_err(&p, at, "a table key", token_name(&tok)));
            }
        }
    }
    Ok(Value::Table(root))
}

fn want_err(p: &Parser, at: usize, expected: &'static str, found: &'static str) -> ParseError {
    ParseError {
        msg: TokErr::Wanted { expected, found }.message(),
        line: Some(p.t.line_of(at)),
        key: None,
    }
}
fn eof_err(p: &Parser) -> ParseError {
    ParseError {
        msg: TokErr::UnexpectedEof.message(),
        line: Some(p.eof_line()),
        key: None,
    }
}

fn skip_inline_ws(p: &mut Parser) -> Result<(), ParseError> {
    while let Some((Token::Whitespace, _, _)) = p.peek()? {
        p.next()?;
    }
    Ok(())
}

fn skip_ws_comments_newlines(p: &mut Parser) -> Result<(), ParseError> {
    loop {
        match p.peek()? {
            Some((Token::Whitespace, _, _))
            | Some((Token::Comment, _, _))
            | Some((Token::Newline, _, _)) => {
                p.next()?;
            }
            _ => return Ok(()),
        }
    }
}

fn parse_key_path(p: &mut Parser) -> Result<Vec<String>, ParseError> {
    let mut keys = Vec::new();
    loop {
        skip_inline_ws(p)?;
        let (tok, at, _) = match p.next()? {
            None => return Err(eof_err(p)),
            Some(x) => x,
        };
        let k = match tok {
            Token::Keylike(s) => s,
            Token::Str { val, multiline } => {
                if multiline {
                    return Err(ParseError {
                        msg: TokErr::MultilineStringKey.message(),
                        line: Some(p.t.line_of(at)),
                        key: None,
                    });
                }
                if val.is_empty() {
                    return Err(ParseError {
                        msg: TokErr::EmptyTableKey.message(),
                        line: Some(p.t.line_of(at)),
                        key: None,
                    });
                }
                val
            }
            t => return Err(want_err(p, at, "a table key", token_name(&t))),
        };
        keys.push(k);
        skip_inline_ws(p)?;
        match p.peek()? {
            Some((Token::Period, _, _)) => {
                p.next()?;
            }
            _ => break,
        }
    }
    Ok(keys)
}

fn insert_value(root: &mut Vec<(String, Value)>, path: &[String], val: Value) {
    if path.is_empty() {
        return;
    }
    let key = path[0].clone();
    if path.len() == 1 {
        if let Some(idx) = root.iter().position(|(k, _)| *k == key) {
            // duplicates are preserved so the deserializer can report them
            root.insert(idx + 1, (key, val));
        } else {
            root.push((key, val));
        }
        return;
    }
    let idx = match root.iter().position(|(k, _)| *k == key) {
        Some(i) => i,
        None => {
            root.push((key.clone(), Value::Table(Vec::new())));
            root.len() - 1
        }
    };
    match &mut root[idx].1 {
        Value::Table(t) => insert_value(t, &path[1..], val),
        Value::Array(arr) => match arr.last_mut() {
            Some(Value::Table(t)) => insert_value(t, &path[1..], val),
            _ => {}
        },
        _ => {}
    }
}

fn adjacent(p: &Parser, prev_end: usize, tok_start: usize) -> bool {
    // no whitespace between the two tokens
    for i in prev_end..tok_start {
        let b = p.t.src[i];
        if b != b' ' && b != b'\t' {
            return false;
        }
    }
    true
}

fn parse_value(p: &mut Parser) -> Result<Value, ParseError> {
    let (tok, at, end) = match p.next()? {
        None => return Err(eof_err(p)),
        Some(x) => x,
    };
    match tok {
        Token::Str { val, .. } => Ok(Value::Str(val)),
        Token::Keylike(s) => number_or_date(p, s, at, end),
        Token::PlusSign => {
            let start = p.t.pos;
            match p.next()? {
                Some((Token::Keylike(s), _, _)) => {
                    let mut v = number_or_date(p, &s, at, p.t.pos)?;
                    if let Value::Float(f) = v {
                        v = Value::Float(f);
                    }
                    if let Value::Int(i) = v {
                        v = Value::Int(i);
                    }
                    if let Value::Bool(_) = v {
                        // "true"/"false" with a leading plus is invalid
                        return Err(num_err(p, at));
                    }
                    Ok(v)
                }
                _ => Err(num_err(p, at)),
            }
        }
        Token::LeftBracket => parse_array(p),
        Token::LeftBrace => parse_inline_table(p),
        Token::Newline => Err(want_err(p, at, "a value", "a newline")),
        t => Err(want_err(p, at, "a value", token_name(&t))),
    }
}

fn num_err(p: &Parser, at: usize) -> ParseError {
    ParseError {
        msg: TokErr::NumberInvalid.message(),
        line: Some(p.t.line_of(at)),
        key: None,
    }
}

fn looks_like_date(s: &str) -> bool {
    let b = s.as_bytes();
    b.len() >= 10
        && b[0].is_ascii_digit()
        && b[1].is_ascii_digit()
        && b[2].is_ascii_digit()
        && b[3].is_ascii_digit()
        && b[4] == b'-'
}

fn number_or_date(p: &mut Parser, s: &str, at: usize, end: usize) -> Result<Value, ParseError> {
    if s.contains('T')
        || s.contains('t')
        || (s.len() > 1 && s[1..].contains('-') && !s.contains("e-") && !s.contains("E-"))
    {
        return consume_datetime(p, s, at);
    }
    if let Some((Token::Colon, st, _)) = p.peek()? {
        if adjacent(p, end, st) {
            return consume_datetime(p, s, at);
        }
    }
    parse_number(p, s, at, end)
}

fn consume_datetime(p: &mut Parser, s: &str, at: usize) -> Result<Value, ParseError> {
    let mut text = s.to_string();
    loop {
        let (t, st, e) = match p.peek()? {
            None => break,
            Some(x) => x,
        };
        if !adjacent(p, p.t.pos_of(st), st) {
            break;
        }
        match t {
            Token::Period => {
                p.next()?;
                text.push('.');
            }
            Token::Colon => {
                p.next()?;
                text.push(':');
            }
            Token::PlusSign => {
                p.next()?;
                text.push('+');
            }
            Token::Keylike(k) => {
                p.next()?;
                text.push_str(&k);
            }
            _ => break,
        }
    }
    // validate loosely: must contain '-' or ':'
    if !text.contains('-') && !text.contains(':') {
        return Err(ParseError {
            msg: TokErr::DateInvalid.message(),
            line: Some(p.t.line_of(at)),
            key: None,
        });
    }
    Ok(Value::Datetime)
}

trait PosOf {
    fn pos_of(&self, start: usize) -> usize;
}
impl PosOf for Tokenizer<'_> {
    fn pos_of(&self, start: usize) -> usize {
        start
    }
}

fn parse_number(p: &mut Parser, s: &str, at: usize, end: usize) -> Result<Value, ParseError> {
    if s == "true" {
        return Ok(Value::Bool(true));
    }
    if s == "false" {
        return Ok(Value::Bool(false));
    }
    if s == "inf" || s == "nan" {
        return Ok(Value::Float(if s == "inf" {
            f64::INFINITY
        } else {
            f64::NAN
        }));
    }
    // gather the fractional / exponent tail
    let mut text = s.to_string();
    if let Some((Token::Period, st, _)) = p.peek()? {
        if adjacent(p, end, st) {
            p.next()?;
            text.push('.');
            match p.next()? {
                Some((Token::Keylike(k), _, e2)) => {
                    text.push_str(&k.replace('_', ""));
                    // exponent continuation
                    if k.ends_with('e') || k.ends_with('E') {
                        if let Some((t2, st2, _)) = p.peek()? {
                            if adjacent(p, e2, st2) {
                                match t2 {
                                    Token::PlusSign => {
                                        p.next()?;
                                        text.push('+');
                                        if let Some((Token::Keylike(k2), _, _)) = p.next()? {
                                            text.push_str(&k2.replace('_', ""));
                                        } else {
                                            return Err(num_err(p, at));
                                        }
                                    }
                                    Token::Keylike(k2) if k2.starts_with('-') => {
                                        p.next()?;
                                        text.push_str(&k2.replace('_', ""));
                                    }
                                    _ => {}
                                }
                            }
                        }
                    }
                }
                _ => return Err(num_err(p, at)),
            }
        }
    }
    let cleaned: String = text.chars().filter(|c| *c != '_').collect();
    if let Some(rest) = cleaned.strip_prefix("0x") {
        return match i64::from_str_radix(rest, 16) {
            Ok(v) => Ok(Value::Int(v)),
            Err(_) => Err(num_err(p, at)),
        };
    }
    if let Some(rest) = cleaned.strip_prefix("0o") {
        return match i64::from_str_radix(rest, 8) {
            Ok(v) => Ok(Value::Int(v)),
            Err(_) => Err(num_err(p, at)),
        };
    }
    if let Some(rest) = cleaned.strip_prefix("0b") {
        return match i64::from_str_radix(rest, 2) {
            Ok(v) => Ok(Value::Int(v)),
            Err(_) => Err(num_err(p, at)),
        };
    }
    let has_dot = cleaned.contains('.');
    let has_exp = cleaned.contains('e') || cleaned.contains('E');
    if has_dot || has_exp {
        return match cleaned.parse::<f64>() {
            Ok(v) => Ok(Value::Float(v)),
            Err(_) => Err(num_err(p, at)),
        };
    }
    let digits = cleaned.trim_start_matches(['+', '-']);
    if digits.len() > 1 && digits.starts_with('0') {
        return Err(num_err(p, at));
    }
    match cleaned.parse::<i64>() {
        Ok(v) => Ok(Value::Int(v)),
        Err(_) => Err(num_err(p, at)),
    }
}

fn parse_array(p: &mut Parser) -> Result<Value, ParseError> {
    let mut out: Vec<Value> = Vec::new();
    let mut kind: Option<u8> = None; // 0 = table, 1 = scalar
    loop {
        skip_ws_comments_newlines(p)?;
        match p.peek()? {
            Some((Token::RightBracket, _, _)) => {
                p.next()?;
                break;
            }
            None => return Err(eof_err(p)),
            _ => {}
        }
        let v = parse_value(p)?;
        let k = match v {
            Value::Table(_) => 0u8,
            _ => 1u8,
        };
        match kind {
            None => kind = Some(k),
            Some(prev) => {
                if prev != k {
                    return Err(ParseError {
                        msg: TokErr::MixedTypes.message(),
                        line: Some(p.t.line_of(p.t.pos)),
                        key: None,
                    });
                }
            }
        }
        out.push(v);
        skip_ws_comments_newlines(p)?;
        match p.peek()? {
            Some((Token::Comma, _, _)) => {
                p.next()?;
            }
            Some((Token::RightBracket, _, _)) => {
                p.next()?;
                break;
            }
            None => return Err(eof_err(p)),
            Some((t, a, _)) => return Err(want_err(p, a, "a comma", token_name(&t))),
        }
    }
    Ok(Value::Array(out))
}

fn parse_inline_table(p: &mut Parser) -> Result<Value, ParseError> {
    let mut out: Vec<(String, Value)> = Vec::new();
    skip_inline_ws(p)?;
    if let Some((Token::RightBrace, _, _)) = p.peek()? {
        p.next()?;
        return Ok(Value::Table(out));
    }
    loop {
        skip_inline_ws(p)?;
        let keys = parse_key_path(p)?;
        skip_inline_ws(p)?;
        match p.next()? {
            Some((Token::Equals, _, _)) => {}
            Some((t, a, _)) => return Err(want_err(p, a, "an equals", token_name(&t))),
            None => return Err(eof_err(p)),
        }
        skip_inline_ws(p)?;
        let v = parse_value(p)?;
        insert_flat(&mut out, &keys, v);
        skip_inline_ws(p)?;
        match p.peek()? {
            Some((Token::Comma, _, _)) => {
                p.next()?;
            }
            Some((Token::RightBrace, _, _)) => {
                p.next()?;
                break;
            }
            None => return Err(eof_err(p)),
            Some((t, a, _)) => return Err(want_err(p, a, "a right brace", token_name(&t))),
        }
    }
    Ok(Value::Table(out))
}

fn insert_flat(t: &mut Vec<(String, Value)>, keys: &[String], v: Value) {
    if keys.len() == 1 {
        if let Some(i) = t.iter().position(|(k, _)| *k == keys[0]) {
            t[i].1 = v;
        } else {
            t.push((keys[0].clone(), v));
        }
        return;
    }
    let idx = match t.iter().position(|(k, _)| *k == keys[0]) {
        Some(i) => i,
        None => {
            t.push((keys[0].clone(), Value::Table(Vec::new())));
            t.len() - 1
        }
    };
    if let Value::Table(inner) = &mut t[idx].1 {
        insert_flat(inner, &keys[1..], v);
    }
}

// ---------------------------------------------------------------------------
// Serializer (toml's `to_string_pretty`)
// ---------------------------------------------------------------------------

pub fn is_bare_key(k: &str) -> bool {
    !k.is_empty() && k.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

pub fn quote_key(k: &str) -> String {
    if is_bare_key(k) {
        k.to_string()
    } else {
        format!("\"{}\"", escape_basic(k))
    }
}

fn escape_basic(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04X}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

fn bad_for_literal_single(c: char) -> bool {
    c == '\'' || ((c as u32) < 0x20 && c != '\t')
}

fn bad_for_literal_multi(c: char) -> bool {
    (c as u32) < 0x20 && c != '\t' && c != '\n'
}

const TRIPLE_Q: &str = "'''";

pub fn write_string(s: &str) -> String {
    if !s.chars().any(bad_for_literal_single) {
        return format!("'{}'", s);
    }
    if !s.chars().any(bad_for_literal_multi) && !s.contains(TRIPLE_Q) && !s.ends_with('\'') {
        if s.contains('\n') {
            return format!("'''\n{}'''", s);
        } else {
            return format!("'''{}'''", s);
        }
    }
    if s.contains('\n') {
        format!("\"\"\"\n{}\"\"\"", escape_multiline(s))
    } else {
        format!("\"{}\"", escape_basic(s))
    }
}

fn escape_multiline(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\n' => out.push('\n'),
            '\r' => out.push_str("\\r"),
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push('\t'),
            '\u{c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04X}", c as u32)),
            c => out.push(c),
        }
    }
    out
}
