    if s == "true" {
        return Ok(Value::Bool(true));
    }
    if s == "false" {
        return Ok(Value::Bool(false));
    }
    if s == "inf" {
        return Ok(Value::Float(f64::INFINITY));
    }
    if s == "nan" {
        return Ok(Value::Float(f64::NAN));
    }
    let mut text = s.to_string();
    if let Some((Token::Period, st, _)) = p.peek()? {
        if adjacent(p, end, st) {
            p.next()?;
            text.push('.');
            match p.next()? {
                Some((Token::Keylike(k), _, e2)) => {
                    text.push_str(&k);
                    if k.ends_with('e') || k.ends_with('E') {
