                                    Token::PlusSign => {
                                        p.next()?;
                                        text.push('+');
                                        match p.next()? {
                                            Some((Token::Keylike(k2), _, _)) => text.push_str(&k2),
                                            _ => return Err(num_err(p, at)),
                                        }
                                    }
                                    Token::Keylike(k2) if k2.starts_with('-') => {
                                        p.next()?;
                                        text.push_str(&k2);
                                    }
                                    _ => {}
                                }
                            }
                        }
                    }
                }
                _ => return Err(num_err(p, at)),
            }
        }
    }
    parse_number_text(&text, p, at)
}

fn num_invalid(p: &Parser, at: usize) -> ParseError {
    ParseError {
        msg: TokErr::NumberInvalid.message(),
        line: Some(p.t.line_of(at)),
        key: None,
    }
}

/// Parse an integer or float literal the way toml 0.5 does.
fn parse_number_text(text: &str, p: &Parser, at: usize) -> Result<Value, ParseError> {
    let (sign, rest) = match text.as_bytes().first() {
        Some(b'+') => (1i64, &text[1..]),
        Some(b'-') => (-1i64, &text[1..]),
        _ => (1i64, text),
    };
    if rest.is_empty() {
        return Err(num_invalid(p, at));
    }
    for (prefix, radix) in [("0x", 16u32), ("0o", 8), ("0b", 2)].iter() {
        if let Some(r) = rest.strip_prefix(prefix) {
            let digits: String = r
                .chars()
                .take_while(|c| c.is_digit(*radix) || *c == '_')
                .filter(|c| *c != '_')
                .collect();
            if digits.is_empty() {
                return Err(num_invalid(p, at));
            }
            return match i64::from_str_radix(&digits, *radix) {
                Ok(v) => Ok(Value::Int(sign * v)),
                Err(_) => Err(num_invalid(p, at)),
            };
        }
    }
    if rest.contains('e') || rest.contains('E') || rest.contains('.') {
        // float
        let mut idx = 0usize;
        let rb: Vec<char> = rest.chars().collect();
        let mut integral = String::new();
        while idx < rb.len() && (rb[idx].is_ascii_digit() || rb[idx] == '_') {
            integral.push(rb[idx]);
            idx += 1;
        }
        if integral.is_empty() {
            return Err(num_invalid(p, at));
        }
        let mut fraction = String::new();
        if idx < rb.len() && rb[idx] == '.' {
            idx += 1;
            while idx < rb.len() && (rb[idx].is_ascii_digit() || rb[idx] == '_') {
                fraction.push(rb[idx]);
                idx += 1;
            }
            if fraction.is_empty() {
                return Err(num_invalid(p, at));
            }
        }
        let mut exponent = String::new();
        if idx < rb.len() && (rb[idx] == 'e' || rb[idx] == 'E') {
            idx += 1;
            if idx < rb.len() && (rb[idx] == '+' || rb[idx] == '-') {
                exponent.push(rb[idx]);
                idx += 1;
            }
            let mut any = false;
            while idx < rb.len() && (rb[idx].is_ascii_digit() || rb[idx] == '_') {
                exponent.push(rb[idx]);
                any = true;
                idx += 1;
            }
            if !any {
                return Err(num_invalid(p, at));
            }
            if idx != rb.len() {
                return Err(num_invalid(p, at));
            }
        }
        let mut ftext = String::new();
        if sign < 0 {
            ftext.push('-');
        }
        ftext.push_str(&integral.replace('_', ""));
        if !fraction.is_empty() {
            ftext.push('.');
            ftext.push_str(&fraction.replace('_', ""));
        }
        if !exponent.is_empty() {
            ftext.push('e');
            ftext.push_str(&exponent.replace('_', ""));
        }
        return match ftext.parse::<f64>() {
            Ok(v) => Ok(Value::Float(v)),
            Err(_) => Err(num_invalid(p, at)),
        };
    }
    let digits: String = rest.chars().filter(|c| *c != '_').collect();
    if digits.is_empty() || !digits.chars().all(|c| c.is_ascii_digit()) {
        return Err(num_invalid(p, at));
    }
    if digits.len() > 1 && digits.starts_with('0') {
        return Err(num_invalid(p, at));
    }
    match digits.parse::<i64>() {
        Ok(v) => Ok(Value::Int(sign * v)),
        Err(_) => Err(num_invalid(p, at)),
    }
}

